insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e7000000-0000-0000-0000-000000000001', 'ukmla', 'ac59de35-f3cd-40a6-bcac-705d85f97bf1',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e7000000-0000-0000-0000-000000000001', 'A', 'The COCP can be started as she is young and has no other cardiovascular risk factors', false, 'Ruled out because migraine with aura is an absolute contraindication (UKMEC 4) to combined hormonal contraception regardless of age or other risk factors, due to stroke risk.', 1),
('e7000000-0000-0000-0000-000000000001', 'B', 'The COCP is UKMEC 2 and can be used with caution and follow-up', false, 'Ruled out because migraine with aura is UKMEC 4 (unacceptable risk), not UKMEC 2; the presence of aura is what drives the contraindication, not the frequency of attacks.', 2),
('e7000000-0000-0000-0000-000000000001', 'C', 'The COCP is contraindicated (UKMEC 4) because of migraine with aura, and a progestogen-only method should be offered instead', true, 'Correct. Migraine with aura at any age is UKMEC 4 for combined hormonal contraception because of a significantly increased risk of ischaemic stroke; progestogen-only methods (POP, implant, injection, IUS) are not restricted by aura and are safe alternatives.', 3),
('e7000000-0000-0000-0000-000000000001', 'D', 'A migraine prophylactic agent should be started before considering any contraceptive choice', false, 'Ruled out because this does not address her contraceptive request and delays appropriate counselling; migraine prophylaxis does not change the UKMEC classification of aura for combined hormonal methods.', 4),
('e7000000-0000-0000-0000-000000000001', 'E', 'Switching to a lower-oestrogen COCP preparation would make it safe to use', false, 'Ruled out because the contraindication with aura relates to any oestrogen-containing method, not the dose; no COCP formulation is safe in the presence of aura.', 5),
('e7000000-0000-0000-0000-000000000002', 'A', 'Continue the COCP but reduce the dose of ethinylestradiol', false, 'Ruled out because at age 35+ with heavy smoking the combination is an absolute contraindication (UKMEC 4); no oestrogen dose is considered safe in this context.', 1),
('e7000000-0000-0000-0000-000000000002', 'B', 'Continue the COCP as she has used it safely for 10 years with no problems', false, 'Ruled out because prior tolerance does not remove risk; age and smoking status are the determining factors, and she has now crossed into the UKMEC 4 category by turning 35.', 2),
('e7000000-0000-0000-0000-000000000002', 'C', 'Continue the COCP but arrange annual blood pressure checks only', false, 'Ruled out because monitoring does not mitigate a UKMEC 4 contraindication; the method itself must be changed, not simply monitored.', 3),
('e7000000-0000-0000-0000-000000000002', 'D', 'Advise her to reduce smoking to fewer than 15 cigarettes per day and continue the COCP unchanged', false, 'Ruled out because even at fewer than 15 cigarettes/day, age 35+ smokers remain UKMEC 3 (caution), and she should stop smoking regardless, but the immediate answer for a 20/day smoker aged 35+ is to change contraceptive method now.', 4),
('e7000000-0000-0000-0000-000000000002', 'E', 'Stop the COCP and switch to a progestogen-only or non-hormonal method, as this is UKMEC 4', true, 'Correct. Age 35 or over combined with smoking 15 or more cigarettes per day is UKMEC 4 for combined hormonal contraception because of a markedly increased risk of arterial and venous thrombosis; the COCP must be stopped and a progestogen-only or non-hormonal method offered.', 5),
('e7000000-0000-0000-0000-000000000003', 'A', 'She should be advised that this counts as a missed pill (>12-hour window), and additional contraception (condoms) is needed for the next 48 hours', true, $x$Correct. Desogestrel-only pills have a 12-hour missed-pill window; being 14 hours late means the pill is 'missed' and ovulation inhibition may be lost, so condoms should be used for 48 hours after restarting, and emergency contraception should be considered given intercourse in the preceding days.$x$, 1),
('e7000000-0000-0000-0000-000000000003', 'B', 'No action is needed, as progestogen-only pills have a 24-hour missed-pill window like the combined pill', false, $x$Ruled out because the 24-hour rule applies to combined pills' 'missed pill' definition differently; desogestrel-only pills specifically have a 12-hour window, beyond which contraceptive protection may be lost.$x$, 2),
('e7000000-0000-0000-0000-000000000003', 'C', 'She should stop the pill immediately and switch to a different contraceptive method', false, 'Ruled out because a single missed pill does not require stopping the method altogether; the correct action is to continue the pill and use additional precautions temporarily.', 3),
('e7000000-0000-0000-0000-000000000003', 'D', 'She should double her next dose to compensate for the missed pill', false, 'Ruled out because doubling the dose is not part of missed-pill guidance for the POP and does not restore protection; the correct advice is additional contraception, not dose adjustment.', 4),
('e7000000-0000-0000-0000-000000000003', 'E', $x$Emergency contraception is not needed because she has already taken today's pill on time$x$, false, $x$Ruled out because taking today's pill on time does not retrospectively cover the period of reduced protection when the previous pill was more than 12 hours late, especially with intercourse in that window.$x$, 5),
('e7000000-0000-0000-0000-000000000004', 'A', 'Levonorgestrel, as it remains fully effective up to 120 hours after intercourse', false, 'Ruled out because levonorgestrel is only licensed and effective up to 72 hours after unprotected intercourse; at 90 hours it would no longer be an appropriate option.', 1),
('e7000000-0000-0000-0000-000000000004', 'B', 'Ulipristal acetate is contraindicated in this situation', false, 'Ruled out because ulipristal acetate is licensed up to 120 hours and would be a reasonable oral option if the IUD is declined or unavailable; it is not contraindicated here.', 2),
('e7000000-0000-0000-0000-000000000004', 'C', 'No emergency contraception is effective beyond 72 hours, so routine follow-up should be arranged instead', false, 'Ruled out because both the copper IUD and ulipristal acetate remain effective up to 120 hours after unprotected intercourse; declining to offer emergency contraception would be inappropriate.', 3),
('e7000000-0000-0000-0000-000000000004', 'D', 'Copper intrauterine device, as it is the most effective option at any point up to 120 hours after unprotected intercourse', true, 'Correct. The copper IUD is the most effective form of emergency contraception (failure rate <1%), can be fitted up to 120 hours after unprotected intercourse (or up to 5 days after the earliest likely ovulation), and is unaffected by body weight or enzyme-inducing drugs; it should be offered as first-line where accessible and acceptable to the patient.', 4),
('e7000000-0000-0000-0000-000000000004', 'E', 'A pregnancy test should be performed immediately and emergency contraception withheld until the result is known', false, 'Ruled out because a pregnancy test at this stage would be uninformative (too early to detect implantation) and would inappropriately delay time-critical emergency contraception.', 5),
('e7000000-0000-0000-0000-000000000005', 'A', $x$DMPA should be stopped immediately at 2 years regardless of the patient's other risk factors$x$, false, 'Ruled out because guidance recommends a risk-benefit review at 2 years, not automatic discontinuation; many women can safely continue if benefits outweigh risks.', 1),
('e7000000-0000-0000-0000-000000000005', 'B', 'Long-term DMPA use is associated with a reversible reduction in bone mineral density, and the risks and benefits of continuing beyond 2 years should be reviewed', true, 'Correct. DMPA causes a reversible decrease in bone mineral density with prolonged use; current guidance recommends reviewing the risks and benefits of continuing beyond 2 years, particularly weighing this against other risk factors for osteoporosis, though it can still be continued if benefits outweigh risks.', 2),
('e7000000-0000-0000-0000-000000000005', 'C', 'DMPA causes an irreversible reduction in bone mineral density that will not recover after stopping', false, 'Ruled out because the reduction in bone mineral density associated with DMPA is generally reversible after discontinuation, particularly in younger women.', 3),
('e7000000-0000-0000-0000-000000000005', 'D', 'DMPA is associated with an increased risk of endometrial cancer and requires annual endometrial biopsy', false, 'Ruled out because DMPA is not associated with increased endometrial cancer risk (progestogens are generally protective against endometrial hyperplasia), and endometrial biopsy is not routinely required.', 4),
('e7000000-0000-0000-0000-000000000005', 'E', 'DMPA should be avoided in women who have previously used it for more than 5 years due to cumulative infertility risk', false, 'Ruled out because DMPA does not cause permanent infertility; return to fertility may simply be delayed (up to a year) after stopping, regardless of duration of use.', 5),
('e7000000-0000-0000-0000-000000000006', 'A', 'Irregular or unpredictable bleeding is a common side effect, and there is a small risk of nerve or vessel injury during insertion into the inner upper arm', true, 'Correct. Irregular bleeding patterns (including amenorrhoea, infrequent, or frequent bleeding) are the most common reason for discontinuation and should be discussed in advance; insertion technique into the inner aspect of the upper arm carries a small but recognised risk of injury to the neurovascular bundle if performed incorrectly.', 1),
('e7000000-0000-0000-0000-000000000006', 'B', 'The implant provides contraceptive cover for 5 years from insertion', false, 'Ruled out because the etonogestrel implant (Nexplanon) is licensed for 3 years of use, not 5; it must be removed or replaced at that point.', 2),
('e7000000-0000-0000-0000-000000000006', 'C', 'Fertility will take up to 12 months to return after removal, similar to the injectable', false, 'Ruled out because fertility returns rapidly after implant removal, typically within days to weeks, unlike the delayed return seen with DMPA.', 3),
('e7000000-0000-0000-0000-000000000006', 'D', 'The implant is contraindicated in women who wish to breastfeed', false, 'Ruled out because progestogen-only implants are considered safe (UKMEC 1) for use during breastfeeding, including from soon after delivery.', 4),
('e7000000-0000-0000-0000-000000000006', 'E', 'Regular bleeding is expected and any irregular bleeding should prompt immediate removal', false, 'Ruled out because irregular bleeding is a common, expected side effect that does not itself mandate removal; it should be discussed and investigated only if persistent, heavy, or otherwise concerning.', 5),
('e7000000-0000-0000-0000-000000000007', 'A', 'Copper intrauterine device', false, 'Ruled out because the copper IUD does not contain progestogen and often worsens menstrual bleeding and dysmenorrhoea rather than improving it.', 1),
('e7000000-0000-0000-0000-000000000007', 'B', 'Levonorgestrel-releasing intrauterine system (IUS)', true, 'Correct. The levonorgestrel IUS is first-line for both contraception and management of heavy menstrual bleeding; it typically reduces menstrual blood loss substantially (often causing amenorrhoea after several months) while providing long-acting, highly effective contraception.', 2),
('e7000000-0000-0000-0000-000000000007', 'C', 'Combined oral contraceptive pill taken continuously without a break', false, 'Ruled out because while COCP can help menstrual symptoms, the IUS is more effective for heavy menstrual bleeding and provides a long-acting option without daily adherence, making it the more appropriate first recommendation here.', 3),
('e7000000-0000-0000-0000-000000000007', 'D', 'Male condoms', false, 'Ruled out because barrier methods provide no benefit for menorrhagia and have a higher failure rate than the IUS for contraception.', 4),
('e7000000-0000-0000-0000-000000000007', 'E', 'Progestogen-only pill', false, 'Ruled out because the POP is less effective than the IUS at reducing heavy menstrual bleeding and requires daily adherence with a narrow missed-pill window for some formulations.', 5),
('e7000000-0000-0000-0000-000000000008', 'A', 'The COCP can be started now since breastfeeding itself provides reliable contraception', false, 'Ruled out because lactational amenorrhoea is only reliable under strict criteria (exclusive breastfeeding, amenorrhoeic, under 6 months), and does not override the UKMEC 4 contraindication to combined hormonal contraception in this period.', 1),
('e7000000-0000-0000-0000-000000000008', 'B', 'The COCP is UKMEC 2 while breastfeeding under 6 weeks and can be started with monitoring', false, 'Ruled out because breastfeeding under 6 weeks postpartum is UKMEC 4, not UKMEC 2, for combined hormonal contraception.', 2),
('e7000000-0000-0000-0000-000000000008', 'C', 'The COCP should not be started now (UKMEC 4 while breastfeeding under 6 weeks postpartum); a progestogen-only method can be started immediately instead', true, 'Correct. Combined hormonal contraception is UKMEC 4 in breastfeeding women less than 6 weeks postpartum because of a theoretical increased VTE risk and possible effects on lactation and infant development; progestogen-only methods (pill, implant, IUS/IUD after appropriate timing) are safe to start immediately postpartum.', 3),
('e7000000-0000-0000-0000-000000000008', 'D', 'Combined hormonal contraception is safe in breastfeeding women at any time postpartum', false, 'Ruled out because the UKMEC category changes with time since delivery and breastfeeding status: it is UKMEC 4 before 6 weeks, UKMEC 2 from 6 weeks to 6 months while breastfeeding.', 4),
('e7000000-0000-0000-0000-000000000008', 'E', 'She should wait until she stops breastfeeding entirely before starting any contraception', false, 'Ruled out because progestogen-only methods can and should be offered immediately postpartum regardless of breastfeeding status; delaying contraception is not appropriate given ongoing fertility risk.', 5),
('e7000000-0000-0000-0000-000000000009', 'A', 'Combined oral contraceptive pill', false, 'Ruled out because enzyme-inducing drugs like carbamazepine increase hepatic metabolism of ethinylestradiol and progestogens, reducing COCP efficacy significantly.', 1),
('e7000000-0000-0000-0000-000000000009', 'B', 'Progestogen-only pill (desogestrel)', false, $x$Ruled out because the POP's efficacy is significantly reduced by enzyme-inducing drugs, as its progestogen is metabolised via the same hepatic pathways.$x$, 2),
('e7000000-0000-0000-0000-000000000009', 'C', 'Subdermal contraceptive implant', false, $x$Ruled out because enzyme inducers reduce serum etonogestrel levels, reducing the implant's contraceptive reliability, so it is not recommended as a sole method with enzyme-inducing antiepileptics.$x$, 3),
('e7000000-0000-0000-0000-000000000009', 'D', 'Contraceptive vaginal ring', false, 'Ruled out because the vaginal ring, like the COCP, contains oestrogen and progestogen that undergo hepatic metabolism affected by enzyme inducers.', 4),
('e7000000-0000-0000-0000-000000000009', 'E', 'Levonorgestrel-releasing intrauterine system (IUS)', true, 'Correct. The IUS acts primarily locally within the uterus and its contraceptive efficacy is not significantly affected by enzyme-inducing drugs, making it (along with the copper IUD and DMPA injection) a preferred choice for women on enzyme-inducing antiepileptics.', 5),
('e7000000-0000-0000-0000-000000000010', 'A', 'The COCP can be safely restarted provided she takes low-dose aspirin concurrently', false, 'Ruled out because concurrent aspirin does not reduce the UKMEC 4 classification or mitigate the substantially increased thrombotic risk of combined hormonal contraception in this context.', 1),
('e7000000-0000-0000-0000-000000000010', 'B', 'The COCP is UKMEC 2 in SLE regardless of antiphospholipid antibody status', false, 'Ruled out because SLE without antiphospholipid antibodies and with no other risk factors may be UKMEC 2, but positive antiphospholipid antibodies specifically raise this to UKMEC 4.', 2),
('e7000000-0000-0000-0000-000000000010', 'C', 'She should switch to the combined contraceptive patch instead of the pill, as this carries a lower thrombosis risk', false, 'Ruled out because the contraceptive patch also contains oestrogen and carries a similar or even slightly higher thrombosis risk profile to the COCP; it is equally UKMEC 4 in this context.', 3),
('e7000000-0000-0000-0000-000000000010', 'D', 'The COCP is contraindicated (UKMEC 4) due to a markedly increased thrombosis risk with positive antiphospholipid antibodies; a progestogen-only or non-hormonal method should be used instead', true, 'Correct. Positive antiphospholipid antibodies, whether in the context of antiphospholipid syndrome or SLE, are UKMEC 4 for combined hormonal contraception because of a substantially increased risk of arterial and venous thrombosis; progestogen-only or non-hormonal methods are the appropriate alternative.', 4),
('e7000000-0000-0000-0000-000000000010', 'E', 'No specific caution is required as thrombosis risk with antiphospholipid antibodies applies only to pregnancy, not contraception', false, 'Ruled out because antiphospholipid antibodies increase thrombosis risk independent of pregnancy, and this risk is significantly compounded by oestrogen-containing contraception.', 5),
('e7000000-0000-0000-0000-000000000011', 'A', 'He can stop using contraception immediately after the procedure as vasectomy is effective from the day it is performed', false, 'Ruled out because vasectomy is not immediately effective; residual sperm can remain viable in the reproductive tract for weeks after the procedure, so ongoing contraception is required until confirmed by semen analysis.', 1),
('e7000000-0000-0000-0000-000000000011', 'B', 'Contraception can be stopped after 2 weeks, once any post-procedure swelling has resolved', false, 'Ruled out because clinical recovery from swelling is unrelated to clearance of residual sperm; confirmation requires semen analysis, not symptom resolution.', 2),
('e7000000-0000-0000-0000-000000000011', 'C', 'Vasectomy provides 100% reliable contraception with no risk of failure, so semen analysis is not required', false, 'Ruled out because vasectomy, while highly effective, has a small recognised failure/recanalisation rate (approximately 1 in 2000), and semen analysis is required to confirm success before relying on it as sole contraception.', 3),
('e7000000-0000-0000-0000-000000000011', 'D', 'He and his partner must continue to use effective contraception until azoospermia is confirmed on semen analysis, usually around 12 weeks post-procedure', true, 'Correct. Vasectomy is not immediately effective, as sperm can remain in the proximal vas deferens for some weeks; effective contraception must continue until post-vasectomy semen analysis (typically at approximately 12 weeks, requiring one or two consecutive samples showing azoospermia) confirms success.', 4),
('e7000000-0000-0000-0000-000000000011', 'E', 'His partner should switch to a more effective contraceptive method rather than relying on his vasectomy at all', false, 'Ruled out because once confirmed successful by semen analysis, vasectomy is a highly effective standalone contraceptive method and does not require the partner to use an additional method long-term.', 5),
('e7000000-0000-0000-0000-000000000012', 'A', 'A BMI of 38 is UKMEC 4 and means the COCP cannot be prescribed under any circumstances', false, 'Ruled out because BMI ≥35 is UKMEC 3 (caution, risks generally outweigh benefits but may be used if no alternative is acceptable), not UKMEC 4 (absolute contraindication).', 1),
('e7000000-0000-0000-0000-000000000012', 'B', 'Obesity does not affect COCP risk; only smoking and age are relevant to VTE risk with the COCP', false, 'Ruled out because obesity is an independent risk factor for VTE with combined hormonal contraception, separate from smoking and age.', 2),
('e7000000-0000-0000-0000-000000000012', 'C', 'The COCP is preferred over the implant or IUS in women with obesity because it does not require a procedure', false, 'Ruled out because ease of administration does not outweigh the increased VTE risk in obesity; methods with lower thrombotic risk are preferred where suitable.', 3),
('e7000000-0000-0000-0000-000000000012', 'D', 'A higher oestrogen dose formulation should be used to counteract reduced absorption in obesity', false, 'Ruled out because increasing oestrogen dose would increase thrombotic risk further rather than mitigate it, and is not standard practice.', 4),
('e7000000-0000-0000-0000-000000000012', 'E', 'A BMI of 35 or above is UKMEC 3 for the COCP due to increased VTE risk, and alternative methods such as the IUS, implant, or DMPA should be discussed as preferable options', true, 'Correct. Obesity (BMI ≥35) is UKMEC 3 for combined hormonal contraception because of an increased risk of venous thromboembolism; while it can be used if no other suitable method is acceptable and risks/benefits are discussed, methods without this restriction (such as the IUS, implant, or DMPA) should be offered as preferable alternatives.', 5),
('e7000000-0000-0000-0000-000000000013', 'A', 'Heavier and more painful periods are a recognised side effect of the copper IUD and can be managed with tranexamic acid or NSAIDs if she wishes to continue this method', true, 'Correct. The copper IUD commonly causes heavier, longer, and more painful periods, particularly in the first few months, though this can persist; this is a well-recognised non-hormonal side effect (unlike the levonorgestrel IUS, which usually reduces bleeding) and can often be managed symptomatically with tranexamic acid and/or NSAIDs, or by switching to a hormonal method if bothersome.', 1),
('e7000000-0000-0000-0000-000000000013', 'B', 'This suggests pelvic infection and she requires urgent antibiotics', false, 'Ruled out because she has no fever, pain, or discharge suggestive of infection, and a negative pregnancy test with typical heavy-bleeding symptoms points to a known device side effect rather than infection.', 2),
('e7000000-0000-0000-0000-000000000013', 'C', 'This is not a recognised side effect of the copper IUD and further gynaecological investigation is required immediately', false, 'Ruled out because heavier, more painful periods are a well-documented and common side effect of the copper IUD, not an unexpected finding requiring urgent investigation in an otherwise well patient.', 3),
('e7000000-0000-0000-0000-000000000013', 'D', 'The IUD must be removed immediately as this indicates device malposition', false, 'Ruled out because heavy bleeding alone, without pain suggestive of expulsion/perforation or missing threads, does not indicate malposition; removal is not immediately mandated but can be offered as an option if symptoms are intolerable.', 4),
('e7000000-0000-0000-0000-000000000013', 'E', 'She should switch to the combined oral contraceptive pill to manage the bleeding while continuing to use the copper IUD simultaneously', false, 'Ruled out because using two contraceptive methods simultaneously for this indication is unnecessary; if bleeding is problematic, switching to the levonorgestrel IUS (which reduces bleeding) is a more logical option than adding the COCP.', 5),
('e7000000-0000-0000-0000-000000000014', 'A', 'Oral fluconazole for presumed vulvovaginal candidiasis', false, 'Ruled out because the clinical picture (atrophic white plaques, figure-of-eight distribution, skin splitting) is not typical of candidiasis, which usually presents with erythema, discharge, and satellite lesions rather than atrophic scarring.', 1),
('e7000000-0000-0000-0000-000000000014', 'B', 'Reassurance only, as this represents normal age-related vulval skin change', false, 'Ruled out because these findings are not a normal variant; lichen sclerosus is a chronic inflammatory dermatosis requiring active treatment and surveillance, not reassurance alone.', 2),
('e7000000-0000-0000-0000-000000000014', 'C', 'A potent topical corticosteroid (such as clobetasol propionate), with advice on emollients and avoiding irritants', true, 'Correct. This presentation (white atrophic plaques in a figure-of-eight distribution around the vulva and perianal skin, with itching and dyspareunia) is characteristic of lichen sclerosus; first-line treatment is a potent topical corticosteroid, alongside emollients and avoidance of soap/irritants, with long-term follow-up because of the small associated risk of vulval squamous cell carcinoma.', 3),
('e7000000-0000-0000-0000-000000000014', 'D', 'Urgent vulval biopsy before any treatment is started', false, 'Ruled out because biopsy is reserved for atypical features, diagnostic uncertainty, or lesions not responding to treatment; a typical presentation can be treated empirically with topical corticosteroids, with biopsy reserved if there is treatment failure or suspicious features.', 4),
('e7000000-0000-0000-0000-000000000014', 'E', 'Topical oestrogen cream for presumed atrophic vaginitis', false, 'Ruled out because topical oestrogen treats vaginal atrophy due to oestrogen deficiency, not the inflammatory, scarring process of lichen sclerosus, which requires potent topical corticosteroids.', 5),
('e7000000-0000-0000-0000-000000000015', 'A', 'Candidal balanitis', false, 'Ruled out because candidal balanitis typically presents with erythema, itching, and sometimes discharge in an acute or subacute setting, not progressive whitish scarring and phimosis over a year.', 1),
('e7000000-0000-0000-0000-000000000015', 'B', 'Balanitis xerotica obliterans (male genital lichen sclerosus)', true, 'Correct. Balanitis xerotica obliterans is the male genital form of lichen sclerosus, presenting with progressive whitish scarring and thickening of the glans and prepuce leading to phimosis; it is managed initially with potent topical corticosteroids, with circumcision considered if phimosis persists or is severe.', 2),
('e7000000-0000-0000-0000-000000000015', 'C', 'Genital warts', false, 'Ruled out because genital warts present as discrete papular or cauliflower-like growths, not diffuse whitish scarring with progressive phimosis.', 3),
('e7000000-0000-0000-0000-000000000015', 'D', 'Primary syphilis (chancre)', false, 'Ruled out because primary syphilis presents as a single painless ulcer, not chronic progressive scarring and phimosis over many months.', 4),
('e7000000-0000-0000-0000-000000000015', 'E', 'Penile psoriasis', false, 'Ruled out because psoriasis typically presents with well-demarcated erythematous plaques rather than the sclerotic whitish scarring and progressive phimosis seen here.', 5),
('e7000000-0000-0000-0000-000000000016', 'A', 'Vulval lichen sclerosus', false, 'Ruled out because lichen sclerosus causes chronic itching and atrophic white plaques, not an acute painful fluctuant swelling.', 1),
('e7000000-0000-0000-0000-000000000016', 'B', 'Inguinal hernia', false, 'Ruled out because an inguinal hernia typically presents as a reducible swelling in the groin above the inguinal ligament, not a fluctuant swelling at the vaginal introitus.', 2),
('e7000000-0000-0000-0000-000000000016', 'C', 'Genital herpes simplex infection', false, 'Ruled out because herpes typically causes multiple painful vesicles/ulcers rather than a single fluctuant abscess-like swelling.', 3),
('e7000000-0000-0000-0000-000000000016', 'D', 'Vulval carcinoma', false, 'Ruled out because vulval carcinoma typically presents as a slow-growing lump or non-healing ulcer in an older woman, not an acute tender fluctuant swelling over 2 days.', 4),
('e7000000-0000-0000-0000-000000000016', 'E', $x$Bartholin's gland abscess$x$, true, $x$Correct. A tender, fluctuant swelling at the posterior/lateral aspect of the vaginal introitus is characteristic of an abscess forming in an obstructed Bartholin's gland duct; management involves incision and drainage (often with word catheter placement or marsupialisation) and antibiotics if there is surrounding cellulitis.$x$, 5),
('e7000000-0000-0000-0000-000000000017', 'A', 'Cryotherapy', false, 'Ruled out because cryotherapy is considered safe and is often first-line for treating genital warts in pregnancy, as it works by physical destruction rather than a systemically absorbed cytotoxic agent.', 1),
('e7000000-0000-0000-0000-000000000017', 'B', 'Reassurance and watchful waiting alone', false, $x$Ruled out because this is not a treatment being asked about for avoidance; while warts may be observed if minimal, active treatment options (like cryotherapy) are commonly still used, and this option doesn't answer the question about which treatment to avoid.$x$, 2),
('e7000000-0000-0000-0000-000000000017', 'C', 'Topical podophyllotoxin', true, 'Correct. Podophyllotoxin (and podophyllin) is contraindicated in pregnancy because it is cytotoxic and teratogenic; cryotherapy is generally considered the safer first-line option for treating genital warts during pregnancy, with imiquimod also usually avoided due to limited safety data.', 3),
('e7000000-0000-0000-0000-000000000017', 'D', 'Referral to genitourinary medicine for specialist review', false, 'Ruled out because referral itself is not a treatment to avoid; specialist input during pregnancy is often appropriate.', 4),
('e7000000-0000-0000-0000-000000000017', 'E', 'Excision under local anaesthetic for larger lesions', false, 'Ruled out because surgical excision is not specifically contraindicated in pregnancy and may be considered for larger or bulky lesions unresponsive to other treatments.', 5),
('e7000000-0000-0000-0000-000000000018', 'A', 'Balanitis xerotica obliterans; treat with potent topical corticosteroid', false, 'Ruled out because balanitis xerotica obliterans presents with chronic whitish scarring and phimosis, not acute erythema with satellite pustules, which is characteristic of candidal infection.', 1),
('e7000000-0000-0000-0000-000000000018', 'B', 'Primary syphilis; treat with intramuscular benzathine penicillin', false, 'Ruled out because syphilis classically causes a single painless indurated ulcer (chancre), not itchy erythema with satellite pustules.', 2),
('e7000000-0000-0000-0000-000000000018', 'C', 'Psoriasis; treat with topical vitamin D analogue', false, 'Ruled out because although penile psoriasis can occur, the described satellite pustules and association with poor diabetic control are classic for candidal infection rather than psoriasis.', 3),
('e7000000-0000-0000-0000-000000000018', 'D', 'Candidal balanitis; treat with topical clotrimazole and optimise glycaemic control', true, 'Correct. Erythema with satellite pustules on the glans in a man with poorly controlled diabetes is characteristic of candidal balanitis; topical imidazole (e.g. clotrimazole) is first-line treatment, and optimising glycaemic control is essential as hyperglycaemia predisposes to candidal infection and recurrence.', 4),
('e7000000-0000-0000-0000-000000000018', 'E', 'Contact dermatitis; treat with topical corticosteroid alone, no antifungal needed', false, 'Ruled out because the described satellite lesions and diabetes association strongly favour candidal infection, which requires antifungal treatment, not corticosteroid alone (which could worsen a fungal infection).', 5),
('e7000000-0000-0000-0000-000000000019', 'A', 'Testicular torsion; arrange immediate surgical exploration', false, $x$Ruled out because torsion typically causes sudden, severe pain, a negative Prehn's sign (no relief with elevation), an absent cremasteric reflex, and a high-riding or horizontal testis, which are not described here; the gradual onset and positive Prehn's sign favour epididymo-orchitis.$x$, 1),
('e7000000-0000-0000-0000-000000000019', 'B', 'Epididymo-orchitis, most likely due to chlamydia or gonorrhoea given his age; arrange STI screening and start empirical antibiotics (e.g. doxycycline, with ceftriaxone if gonorrhoea is not excluded)', true, $x$Correct. Gradual-onset unilateral scrotal pain with a tender swollen epididymis, positive Prehn's sign, and intact cremasteric reflex is typical of epididymo-orchitis rather than torsion; in sexually active men under 35 the most likely causative organisms are Chlamydia trachomatis and Neisseria gonorrhoeae, so empirical antibiotics covering these (with STI screening) are appropriate while awaiting results.$x$, 2),
('e7000000-0000-0000-0000-000000000019', 'C', 'Testicular tumour; arrange urgent ultrasound and refer to urology two-week-wait', false, 'Ruled out because testicular tumours are usually painless masses rather than acutely painful, tender, swollen epididymis with dysuria, which points instead to an infective/inflammatory process.', 3),
('e7000000-0000-0000-0000-000000000019', 'D', 'Inguinal hernia; refer for elective surgical repair', false, 'Ruled out because an inguinal hernia would typically present as a reducible groin/scrotal swelling with a cough impulse, not tenderness confined to the epididymis with dysuria.', 4),
('e7000000-0000-0000-0000-000000000019', 'E', 'Reassurance only, as this is likely a self-limiting viral illness', false, 'Ruled out because epididymo-orchitis due to a sexually transmitted or urinary pathogen requires antibiotic treatment and STI screening, not reassurance alone, to prevent complications and onward transmission.', 5),
('e7000000-0000-0000-0000-000000000020', 'A', 'Urgent urological referral for immediate surgical exploration, without waiting for imaging if this would delay treatment', true, $x$Correct. This presentation (sudden severe pain, high-riding horizontal testis, absent cremasteric reflex, negative Prehn's sign) is classic for testicular torsion, a time-critical surgical emergency; testicular viability falls rapidly with time, so urgent surgical exploration should not be delayed for imaging if this would push beyond the window for salvage.$x$, 1),
('e7000000-0000-0000-0000-000000000020', 'B', 'Arrange scrotal ultrasound with Doppler studies before making any further decisions', false, 'Ruled out because in a clinically clear case of torsion, imaging should not delay definitive surgical exploration, as testicular salvage is highly time-dependent; ultrasound may be used only if diagnosis is genuinely uncertain and would not significantly delay surgery.', 2),
('e7000000-0000-0000-0000-000000000020', 'C', 'Start broad-spectrum antibiotics and reassess in 24 hours', false, 'Ruled out because antibiotics have no role in torsion, which is a mechanical/vascular emergency, not an infective process, and delaying treatment risks testicular loss.', 3),
('e7000000-0000-0000-0000-000000000020', 'D', 'Discharge with analgesia and outpatient urology follow-up in one week', false, 'Ruled out because testicular torsion is a surgical emergency with a narrow window for salvage (ideally within 6 hours of onset); discharge would risk testicular infarction and loss.', 4),
('e7000000-0000-0000-0000-000000000020', 'E', 'Attempt manual detorsion in the emergency department and discharge if pain resolves', false, 'Ruled out because although manual detorsion can be attempted as a temporising measure by experienced clinicians, it does not replace the need for urgent surgical exploration and fixation, and the patient should not be discharged without surgical assessment.', 5),
('e7000000-0000-0000-0000-000000000021', 'A', 'Varicocele', false, $x$Ruled out because a varicocele classically feels like a 'bag of worms', is more common on the left side, decompresses on lying flat, and does not transilluminate, unlike the fluid-filled swelling described here.$x$, 1),
('e7000000-0000-0000-0000-000000000021', 'B', 'Testicular tumour', false, 'Ruled out because testicular tumours typically present as a firm, painless swelling or nodule within the testis itself, which does not transilluminate, rather than a separate fluctuant fluid collection.', 2),
('e7000000-0000-0000-0000-000000000021', 'C', 'Hydrocele', true, 'Correct. A painless, soft, fluctuant scrotal swelling that transilluminates brightly and in which the testis can be palpated separately (or is difficult to feel because it is surrounded by fluid) is characteristic of a hydrocele, a collection of fluid within the tunica vaginalis.', 3),
('e7000000-0000-0000-0000-000000000021', 'D', 'Inguinal hernia', false, 'Ruled out because an inguinal hernia typically extends from the inguinal canal, may be reducible, often has a cough impulse, and does not usually transilluminate as brightly as a simple fluid collection.', 4),
('e7000000-0000-0000-0000-000000000021', 'E', 'Epididymal cyst', false, 'Ruled out because an epididymal cyst is typically a small, discrete, cystic swelling separate from and posterior to the testis (arising from the epididymis), rather than a swelling that generally surrounds the testis, though both can transilluminate; the description here of a swelling around the testis is more typical of a hydrocele.', 5),
('e7000000-0000-0000-0000-000000000022', 'A', 'Genital warts', false, 'Ruled out because genital warts (condylomata acuminata) typically appear as irregular, cauliflower-like or filiform papules rather than the uniform, dome-shaped, centrally umbilicated papules described here.', 1),
('e7000000-0000-0000-0000-000000000022', 'B', 'Molluscum contagiosum', true, 'Correct. Small, firm, umbilicated, pearly papules are classic for molluscum contagiosum, caused by a poxvirus; in adults it can be sexually transmitted, so a full STI screen should be offered, and lesions are usually self-limiting, though treatment (e.g. cryotherapy) can be considered if persistent or bothersome.', 2),
('e7000000-0000-0000-0000-000000000022', 'C', 'Pearly penile papules', false, 'Ruled out because pearly penile papules are typically arranged in rows around the corona of the glans and lack central umbilication, distinguishing them from molluscum contagiosum.', 3),
('e7000000-0000-0000-0000-000000000022', 'D', 'Primary genital herpes', false, 'Ruled out because herpes presents with painful vesicles/ulcers rather than firm, painless, umbilicated papules.', 4),
('e7000000-0000-0000-0000-000000000022', 'E', 'Secondary syphilis (condylomata lata)', false, 'Ruled out because condylomata lata are broad, flat, moist plaques associated with systemic features of secondary syphilis, not small pearly umbilicated papules.', 5),
('e7000000-0000-0000-0000-000000000023', 'A', 'Urgent referral for vulval biopsy to exclude vulval squamous cell carcinoma', true, 'Correct. A new, non-healing, indurated or ulcerated vulval lesion in a woman with long-standing lichen sclerosus is a red flag for vulval squamous cell carcinoma, which arises in a small proportion of lichen sclerosus cases; any lesion that fails to respond to treatment or has atypical features requires urgent biopsy to exclude malignancy.', 1),
('e7000000-0000-0000-0000-000000000023', 'B', 'Increase the potency of the topical corticosteroid and review in 3 months', false, 'Ruled out because a non-healing, ulcerated lesion unresponsive to treatment is a red flag that should prompt urgent biopsy, not simply escalating the same treatment and delaying review for months.', 2),
('e7000000-0000-0000-0000-000000000023', 'C', 'Reassure that this is an expected feature of chronic lichen sclerosus requiring no further action', false, 'Ruled out because a new area of ulceration or induration that fails to heal is not an expected benign feature and requires exclusion of malignant transformation.', 3),
('e7000000-0000-0000-0000-000000000023', 'D', 'Start a course of oral antibiotics for a presumed secondary bacterial infection', false, 'Ruled out because there are no signs described suggestive of infection (such as purulent discharge, cellulitis, or fever); the priority is to exclude malignancy given the risk factors and treatment resistance.', 4),
('e7000000-0000-0000-0000-000000000023', 'E', 'Arrange a repeat course of antifungal cream for presumed candidal superinfection', false, 'Ruled out because there is nothing to suggest a fungal cause here, and empirical antifungal treatment would inappropriately delay investigation of a potentially malignant lesion.', 5),
('e7000000-0000-0000-0000-000000000024', 'A', 'Treat with topical podophyllotoxin as for genital warts', false, 'Ruled out because pearly penile papules are not warts and do not require antiviral or destructive wart treatments; treating them as such is unnecessary and can cause discomfort without benefit.', 1),
('e7000000-0000-0000-0000-000000000024', 'B', 'Refer urgently to genitourinary medicine for biopsy to exclude malignancy', false, 'Ruled out because the classic, symmetrical, longstanding appearance described is diagnostic of a benign variant, and urgent biopsy is not required.', 2),
('e7000000-0000-0000-0000-000000000024', 'C', 'Arrange a full STI screen as these lesions suggest a sexually transmitted infection', false, 'Ruled out because pearly penile papules are not caused by any infectious or sexually transmitted process; an STI screen is not indicated based on this finding alone.', 3),
('e7000000-0000-0000-0000-000000000024', 'D', 'Reassurance that these are pearly penile papules, a normal anatomical variant that does not require treatment', true, 'Correct. Pearly penile papules are a common, entirely benign anatomical variant found in a substantial minority of men, arranged in one or two symmetrical rows around the corona of the glans; they are not sexually transmitted, not infectious, and require no treatment beyond reassurance.', 4),
('e7000000-0000-0000-0000-000000000024', 'E', 'Start a course of oral antiviral therapy for suspected genital herpes', false, 'Ruled out because the described lesions are asymptomatic, uniform, and longstanding, which is inconsistent with herpes, and antiviral treatment is not indicated.', 5),
('e7000000-0000-0000-0000-000000000025', 'A', 'Oral antibiotics and outpatient follow-up in 48 hours', false, 'Ruled out because this is a rapidly progressive, life-threatening necrotising soft tissue infection requiring immediate inpatient management with IV antibiotics and emergency surgery, not outpatient oral treatment.', 1),
('e7000000-0000-0000-0000-000000000025', 'B', 'Topical antiseptic dressings and observation on the ward', false, 'Ruled out because necrotising fasciitis requires urgent surgical debridement of all necrotic tissue; topical treatment alone will not control the rapidly progressive infection and risks fatal sepsis.', 2),
('e7000000-0000-0000-0000-000000000025', 'C', 'CT scan of the abdomen and pelvis before any other intervention, with treatment deferred until imaging is complete', false, 'Ruled out because although imaging can sometimes support diagnosis, it should not delay life-saving surgical intervention in a patient with a strong clinical picture of necrotising fasciitis; treatment (antibiotics, resuscitation, surgical referral) should begin immediately and in parallel.', 3),
('e7000000-0000-0000-0000-000000000025', 'D', 'Incision and drainage under local anaesthetic in the emergency department', false, 'Ruled out because necrotising fasciitis requires formal, extensive surgical debridement under general anaesthesia in theatre by a surgical team, not a limited bedside incision and drainage procedure.', 4),
('e7000000-0000-0000-0000-000000000025', 'E', 'Urgent surgical referral for emergency debridement, alongside broad-spectrum intravenous antibiotics and aggressive resuscitation', true, $x$Correct. This presentation (rapidly progressive perineal/scrotal pain disproportionate to examination findings, skin discolouration, crepitus, fever, and systemic upset in a diabetic patient) is classic for Fournier's gangrene, a necrotising fasciitis of the perineum; this is a surgical emergency requiring immediate broad-spectrum intravenous antibiotics, fluid resuscitation, and urgent surgical debridement, as mortality rises sharply with any delay.$x$, 5),
('e7000000-0000-0000-0000-000000000026', 'A', 'Vulvovaginal candidiasis; treat with topical clotrimazole', false, $x$Ruled out because candidiasis typically causes itching, thick white 'cottage cheese' discharge, and a normal or low vaginal pH, not the malodorous discharge, raised pH, and clue cells described here.$x$, 1),
('e7000000-0000-0000-0000-000000000026', 'B', 'Bacterial vaginosis; treat with oral or topical metronidazole', true, 'Correct. Thin, grey-white, fishy-smelling discharge without significant itching, a raised vaginal pH (>4.5), and clue cells on microscopy fulfil the Amsel criteria for bacterial vaginosis, caused by an overgrowth of anaerobic organisms (notably Gardnerella vaginalis) replacing normal lactobacilli; first-line treatment is oral or topical (intravaginal) metronidazole.', 2),
('e7000000-0000-0000-0000-000000000026', 'C', 'Trichomonas vaginalis infection; treat with metronidazole and refer for partner treatment', false, $x$Ruled out because although trichomoniasis is also treated with metronidazole, it typically causes a frothy yellow-green discharge with vulvovaginal irritation and sometimes a 'strawberry cervix', and microscopy would show motile flagellated protozoa rather than clue cells.$x$, 3),
('e7000000-0000-0000-0000-000000000026', 'D', 'Chlamydial cervicitis; treat with doxycycline', false, 'Ruled out because chlamydia is often asymptomatic or causes mucopurulent cervical discharge/bleeding, and diagnosis is by NAAT, not by vaginal pH and clue cells on microscopy.', 4),
('e7000000-0000-0000-0000-000000000026', 'E', 'Atrophic vaginitis; treat with topical oestrogen', false, 'Ruled out because atrophic vaginitis occurs due to oestrogen deficiency (typically postmenopausal), presenting with dryness and sometimes spotting, not the classic discharge, odour, and clue cells described here.', 5),
('e7000000-0000-0000-0000-000000000027', 'A', 'PEP is not indicated as more than 12 hours have already passed since exposure', false, 'Ruled out because PEP remains effective and should be offered up to 72 hours after exposure, not only within the first 12 hours; 20 hours is well within the effective window.', 1),
('e7000000-0000-0000-0000-000000000027', 'B', 'Perform an HIV test now; if negative, no PEP is required', false, 'Ruled out because an HIV test performed shortly after a single exposure cannot detect an infection acquired from that exposure (window period), and a negative result at this point does not exclude the need for PEP.', 2),
('e7000000-0000-0000-0000-000000000027', 'C', 'Advise the patient to return only if symptoms of seroconversion illness develop', false, 'Ruled out because waiting for symptoms would place the patient outside the effective window for PEP; PEP should be started proactively as soon as possible after a significant exposure.', 3),
('e7000000-0000-0000-0000-000000000027', 'D', 'Start PrEP (pre-exposure prophylaxis) rather than PEP, as this is more appropriate after a single exposure', false, 'Ruled out because PrEP is for ongoing protection before future exposures in higher-risk individuals; after a specific high-risk exposure that has already occurred, PEP (a short post-exposure course) is the appropriate intervention.', 4),
('e7000000-0000-0000-0000-000000000027', 'E', 'Start HIV post-exposure prophylaxis (PEP) as soon as possible, ideally within 24 hours and no later than 72 hours after exposure', true, 'Correct. PEP after sexual exposure (PEPSE) should be started as soon as possible after a high-risk exposure, ideally within 24 hours and up to a maximum of 72 hours, as efficacy decreases with time; a typical regimen is a combination antiretroviral course (e.g. tenofovir/emtricitabine plus raltegravir) for 28 days, with baseline and follow-up HIV testing.', 5),
('e7000000-0000-0000-0000-000000000028', 'A', 'Pre-exposure prophylaxis (PrEP) with tenofovir/emtricitabine, alongside regular HIV testing and renal function monitoring', true, $x$Correct. PrEP with tenofovir disoproxil/emtricitabine, taken daily or using an event-based ('2-1-1') regimen, is highly effective at reducing the risk of HIV acquisition in individuals at ongoing substantial risk, such as this man; it requires baseline and regular HIV testing (to avoid using PrEP alone in undiagnosed infection, which risks resistance) and periodic renal function monitoring due to tenofovir's nephrotoxic potential.$x$, 1),
('e7000000-0000-0000-0000-000000000028', 'B', 'Post-exposure prophylaxis (PEP) taken continuously as an ongoing preventive strategy', false, 'Ruled out because PEP is intended as a short course after a specific high-risk exposure, not for continuous ongoing prevention; PrEP is the appropriate strategy for ongoing risk.', 2),
('e7000000-0000-0000-0000-000000000028', 'C', 'Hepatitis B vaccination alone is sufficient to reduce his risk of HIV acquisition', false, 'Ruled out because hepatitis B vaccination protects against hepatitis B, not HIV; while it should also be offered given his risk profile, it does not address his HIV prevention needs.', 3),
('e7000000-0000-0000-0000-000000000028', 'D', 'Reassurance that regular HIV testing alone is an adequate risk-reduction strategy', false, 'Ruled out because testing alone identifies infection after it has occurred but does not reduce his risk of acquiring HIV; PrEP is a proactive preventive measure that this patient is likely to benefit from given his risk profile.', 4),
('e7000000-0000-0000-0000-000000000028', 'E', 'Advise strict monogamy as the only appropriate intervention', false, 'Ruled out because this is not a realistic or appropriate sole clinical recommendation, and does not address his stated ongoing risk; evidence-based preventive options such as PrEP should be offered.', 5),
('e7000000-0000-0000-0000-000000000029', 'A', 'Testing is not useful until 6 months after exposure', false, 'Ruled out because modern combined antigen/antibody assays have a much shorter window period than older tests, and testing from around 4 weeks onward with confirmation at 8-12 weeks is now standard, not waiting 6 months.', 1),
('e7000000-0000-0000-0000-000000000029', 'B', 'A negative test today definitively excludes HIV infection from this exposure', false, 'Ruled out because at only 3 weeks post-exposure she may still be within the window period, so a negative result now cannot be considered fully conclusive without a later confirmatory test.', 2),
('e7000000-0000-0000-0000-000000000029', 'C', 'A 4th generation HIV antigen/antibody test can be performed now, but a negative result at 3 weeks should be confirmed with a repeat test at around 8-12 weeks after exposure', true, 'Correct. Modern 4th generation combined antigen/antibody tests can detect most infections from around 4 weeks post-exposure, but to reliably exclude infection from this specific exposure, a confirmatory test at 8-12 weeks is recommended, as a small proportion of individuals may still be within the window period at 3 weeks.', 3),
('e7000000-0000-0000-0000-000000000029', 'D', 'Only a rapid point-of-care antibody test should be used, as it is more sensitive than laboratory testing in early infection', false, 'Ruled out because point-of-care antibody-only tests are generally less sensitive than laboratory-based 4th generation antigen/antibody tests, particularly in early infection, and should not be preferred over laboratory testing when window-period accuracy matters.', 4),
('e7000000-0000-0000-0000-000000000029', 'E', 'HIV testing should be deferred until symptoms of seroconversion illness appear', false, 'Ruled out because testing should not be delayed based on symptoms; many infections are asymptomatic, and proactive testing at appropriate intervals is the correct approach regardless of symptoms.', 5),
('e7000000-0000-0000-0000-000000000030', 'A', 'Infectious mononucleosis due to Epstein-Barr virus; no further testing is required given the clinical picture', false, 'Ruled out because the heterophile antibody test is negative, making EBV mononucleosis less likely, and the recent high-risk sexual exposure raises specific concern for HIV seroconversion, which should be actively tested for.', 1),
('e7000000-0000-0000-0000-000000000030', 'B', 'Secondary syphilis; treat empirically with benzathine penicillin without further testing', false, 'Ruled out because although secondary syphilis can cause rash and systemic symptoms, empirical treatment without confirmatory testing is not appropriate, and the described sore throat and glandular fever-like illness with recent sexual exposure should specifically raise concern for HIV seroconversion, which needs to be tested for.', 2),
('e7000000-0000-0000-0000-000000000030', 'C', 'Simple viral upper respiratory tract infection; reassure and advise symptomatic treatment only', false, 'Ruled out because this label would miss the important differential of HIV seroconversion illness, which requires specific testing given the risk exposure and symptom pattern.', 3),
('e7000000-0000-0000-0000-000000000030', 'D', 'Primary HIV infection (seroconversion illness); arrange an HIV test', true, 'Correct. Fever, sore throat, malaise, maculopapular rash, and lymphadenopathy 2-4 weeks after a high-risk sexual exposure is classic for HIV seroconversion illness, which mimics infectious mononucleosis; a negative Monospot test makes glandular fever less likely and should prompt HIV testing, as this presentation is frequently missed.', 4),
('e7000000-0000-0000-0000-000000000030', 'E', 'Streptococcal pharyngitis; treat with penicillin V and no further tests', false, 'Ruled out because the widespread rash and lymphadenopathy do not fit a simple streptococcal pharyngitis, and the recent sexual risk exposure means HIV seroconversion must be actively excluded.', 5),
('e7000000-0000-0000-0000-000000000031', 'A', 'Community-acquired bacterial pneumonia; treat with amoxicillin', false, 'Ruled out because bacterial pneumonia typically presents more acutely with focal consolidation and productive cough, not this subacute, exertion-related pattern with bilateral ground-glass changes typical of PCP in advanced HIV.', 1),
('e7000000-0000-0000-0000-000000000031', 'B', 'Pulmonary tuberculosis; start standard quadruple anti-tuberculous therapy without further investigation', false, 'Ruled out because although TB is an important differential in HIV and should be actively investigated, the described exertional desaturation and bilateral ground-glass pattern are more classic for PCP, and empirical anti-TB therapy should not be started without appropriate diagnostic workup.', 2),
('e7000000-0000-0000-0000-000000000031', 'C', $x$Kaposi's sarcoma involving the lungs; refer for oncological assessment$x$, false, $x$Ruled out because pulmonary Kaposi's sarcoma is a less common and later consideration, and the described clinical and radiological pattern is far more typical of PCP in a patient with this CD4 count and presentation.$x$, 3),
('e7000000-0000-0000-0000-000000000031', 'D', 'Congestive heart failure; start diuretics and arrange echocardiography', false, 'Ruled out because there is no other clinical evidence of heart failure provided, and the combination of advanced HIV, subacute course, and bilateral ground-glass changes with exertional desaturation is classic for an opportunistic infection, specifically PCP.', 4),
('e7000000-0000-0000-0000-000000000031', 'E', 'Pneumocystis jirovecii pneumonia (PCP); treat with high-dose co-trimoxazole', true, 'Correct. Subacute progressive breathlessness, dry cough, exertional desaturation, and bilateral perihilar ground-glass changes on chest X-ray in a patient with advanced HIV (CD4 <200) is characteristic of Pneumocystis jirovecii pneumonia, an AIDS-defining illness; first-line treatment is high-dose co-trimoxazole (with corticosteroids added if hypoxaemia is significant).', 5),
('e7000000-0000-0000-0000-000000000032', 'A', 'Caesarean section is mandatory for all HIV-positive women regardless of viral load', false, 'Ruled out because caesarean section is not universally required; with an undetectable viral load near delivery, vaginal delivery is an appropriate and recommended option.', 1),
('e7000000-0000-0000-0000-000000000032', 'B', 'Antiretroviral therapy should be stopped during pregnancy to avoid fetal drug exposure', false, 'Ruled out because antiretroviral therapy should be continued (and optimised) throughout pregnancy to maintain viral suppression and minimise the risk of vertical transmission; stopping treatment would increase transmission risk.', 2),
('e7000000-0000-0000-0000-000000000032', 'C', 'Breastfeeding should be actively encouraged regardless of viral load as antiretrovirals fully eliminate transmission risk via breast milk', false, 'Ruled out because while risk is much reduced with an undetectable viral load, UK guidance still generally recommends formula feeding as the safest option to eliminate any residual risk of transmission via breast milk, with individualised discussion for women who wish to breastfeed.', 3),
('e7000000-0000-0000-0000-000000000032', 'D', 'Vaginal delivery can be planned, as her viral load is undetectable (<50 copies/mL) close to delivery', true, 'Correct. When maternal HIV viral load is well controlled and undetectable (typically <50 copies/mL) close to the time of delivery, vaginal delivery is recommended, as the risk of vertical transmission is very low; caesarean section is reserved for women with detectable or high viral loads (generally >400 copies/mL) closer to delivery, or other standard obstetric indications.', 4),
('e7000000-0000-0000-0000-000000000032', 'E', $x$No neonatal treatment is required if the mother's viral load is undetectable$x$, false, 'Ruled out because neonatal post-exposure prophylaxis (typically a course of antiretroviral medication) is still given to the baby after birth, with the specific regimen and duration depending on the level of maternal viral suppression and other risk factors.', 5),
('e7000000-0000-0000-0000-000000000033', 'A', 'Wash the wound with soap and water, report the incident to occupational health immediately, and assess the risk of transmission based on the injury and source patient, with testing of both as appropriate', true, $x$Correct. Immediate first aid (washing, encouraging bleeding, not sucking the wound) should be followed by prompt reporting to occupational health, who will assess risk factors (needle type, depth, visible blood, source patient's risk factors and testing where consent can be obtained) to determine whether PEP and further monitoring are needed.$x$, 1),
('e7000000-0000-0000-0000-000000000033', 'B', 'No action is needed unless symptoms develop', false, 'Ruled out because needlestick injuries require immediate risk assessment and possible initiation of post-exposure prophylaxis; waiting for symptoms would miss the window for effective PEP.', 2),
('e7000000-0000-0000-0000-000000000033', 'C', 'Squeeze and suck the wound to remove contaminated blood', false, 'Ruled out because sucking the wound is not recommended; the wound should be washed with soap and water and gentle bleeding encouraged, without sucking.', 3),
('e7000000-0000-0000-0000-000000000033', 'D', 'Start antibiotics immediately to prevent bacterial infection, with no further action required', false, 'Ruled out because the primary concern after a needlestick injury from an unknown-status source is blood-borne virus transmission (HIV, hepatitis B, hepatitis C), which requires specific risk assessment and possible PEP, not simply antibiotics for bacterial infection.', 4),
('e7000000-0000-0000-0000-000000000033', 'E', 'Wait until the end of the shift before reporting the incident, as this is not urgent', false, 'Ruled out because prompt reporting is essential, as PEP for HIV is most effective when started as soon as possible, ideally within hours of exposure.', 5),
('e7000000-0000-0000-0000-000000000034', 'A', 'Successful vaccination against hepatitis B', false, 'Ruled out because vaccination produces isolated anti-HBs positivity without HBsAg or anti-HBc positivity; the presence of HBsAg and anti-HBc here indicates natural infection, not vaccine-induced immunity.', 1),
('e7000000-0000-0000-0000-000000000034', 'B', 'Past infection with hepatitis B that has now resolved with immunity', false, 'Ruled out because resolved past infection typically shows HBsAg negative, anti-HBc positive, and anti-HBs positive; here HBsAg remains positive, indicating ongoing rather than resolved infection.', 2),
('e7000000-0000-0000-0000-000000000034', 'C', 'Chronic hepatitis B infection with low replicative activity (HBeAg-negative phase)', true, 'Correct. Persistent HBsAg positivity (present for more than 6 months would confirm chronicity) with anti-HBc IgG positivity indicates ongoing (chronic) infection rather than past cleared infection; HBeAg negativity with anti-HBe positivity suggests seroconversion to a lower-replicative phase, though hepatitis B viral load and liver function should still be assessed as some HBeAg-negative patients have significant ongoing viral replication (precore mutant).', 3),
('e7000000-0000-0000-0000-000000000034', 'D', 'Acute hepatitis B infection in the highly infectious early phase', false, 'Ruled out because acute infection in the highly infectious phase would typically show HBeAg positivity (reflecting high viral replication) alongside HBsAg and anti-HBc IgM; here HBeAg is negative and anti-HBe is positive, more consistent with a lower-replicative chronic phase, and anti-HBc is IgG rather than IgM.', 4),
('e7000000-0000-0000-0000-000000000034', 'E', 'No evidence of ever being exposed to hepatitis B', false, 'Ruled out because HBsAg and anti-HBc positivity clearly indicate hepatitis B infection, not an absence of exposure.', 5),
('e7000000-0000-0000-0000-000000000035', 'A', 'Start direct-acting antiviral treatment immediately based on the antibody result alone', false, 'Ruled out because antibody positivity alone does not confirm active infection; treatment should only be started after confirming ongoing viraemia with HCV RNA testing.', 1),
('e7000000-0000-0000-0000-000000000035', 'B', 'Test for hepatitis C RNA (PCR) to confirm active infection, as antibody positivity alone does not distinguish current infection from past cleared infection', true, 'Correct. A positive hepatitis C antibody test indicates exposure to the virus but does not distinguish between active/chronic infection and past infection that has spontaneously cleared; HCV RNA (PCR) testing is required to confirm whether the virus is still present, which determines whether treatment (with direct-acting antivirals) is needed.', 2),
('e7000000-0000-0000-0000-000000000035', 'C', 'Reassure the patient that antibody positivity means he has lifelong immunity and no further action is needed', false, 'Ruled out because unlike hepatitis A or B (after vaccination), hepatitis C antibody positivity does not confer protective immunity and does not exclude ongoing active infection, which requires RNA testing to clarify.', 3),
('e7000000-0000-0000-0000-000000000035', 'D', 'Repeat the antibody test in 6 months without further action now', false, 'Ruled out because the appropriate next step to determine current infection status is HCV RNA testing, not simply repeating the antibody test, which will likely remain positive regardless of whether the virus has cleared.', 4),
('e7000000-0000-0000-0000-000000000035', 'E', 'Arrange hepatitis C vaccination to prevent progression to chronic infection', false, 'Ruled out because there is no vaccine currently available for hepatitis C; management relies on diagnosis via RNA testing and treatment with direct-acting antivirals if active infection is confirmed.', 5),
('e7000000-0000-0000-0000-000000000036', 'A', 'He must continue to use condoms at all times as there remains a significant risk of transmission regardless of viral load', false, 'Ruled out because this does not reflect current evidence; a sustained undetectable viral load effectively eliminates the risk of sexual HIV transmission, which is the basis of U=U counselling.', 1),
('e7000000-0000-0000-0000-000000000036', 'B', 'His partner should start post-exposure prophylaxis before every sexual encounter as a precaution', false, 'Ruled out because with a sustained undetectable viral load there is no HIV transmission risk requiring PEP; this would be an unnecessary and inappropriate recommendation.', 2),
('e7000000-0000-0000-0000-000000000036', 'C', 'Undetectable viral load only reduces transmission risk by around 50%', false, 'Ruled out because this significantly understates the evidence; sustained viral suppression reduces sexual transmission risk to effectively zero, not merely by half.', 3),
('e7000000-0000-0000-0000-000000000036', 'D', $x$A sustained undetectable viral load on effective treatment means he cannot sexually transmit HIV to his partner ('undetectable = untransmittable', U=U), though condoms still offer protection against other STIs and unplanned pregnancy$x$, true, 'Correct. Robust evidence has established that people living with HIV who maintain a sustained undetectable viral load on effective antiretroviral therapy have no risk of sexually transmitting HIV to their partners (U=U); this is important counselling for reducing stigma and anxiety, though condoms remain relevant for prevention of other STIs and pregnancy.', 4),
('e7000000-0000-0000-0000-000000000036', 'E', 'His partner should start PrEP instead of relying on his treatment status', false, $x$Ruled out because with a sustained undetectable viral load, sexual transmission risk is effectively eliminated, making additional PrEP for the partner unnecessary purely on this basis, though it remains the partner's choice.$x$, 5),
('e7000000-0000-0000-0000-000000000037', 'A', 'Herpes simplex oesophagitis', false, 'Ruled out because although HSV oesophagitis is a differential in immunosuppression, the presence of typical oral candidal plaques that scrape off makes candidiasis far more likely as the underlying cause here.', 1),
('e7000000-0000-0000-0000-000000000037', 'B', 'Gastro-oesophageal reflux disease', false, 'Ruled out because GORD does not typically cause visible oral white plaques, and in a patient with advanced HIV and these findings, an opportunistic infection is much more likely than simple reflux.', 2),
('e7000000-0000-0000-0000-000000000037', 'C', 'Oesophageal candidiasis', true, 'Correct. Odynophagia and dysphagia in a patient with advanced HIV (CD4 <200) and evidence of oral candidiasis (white plaques that scrape off) strongly suggests oesophageal candidiasis, an AIDS-defining illness; treatment is with systemic antifungal therapy (e.g. fluconazole), and this presentation should prompt urgent initiation of antiretroviral therapy.', 3),
('e7000000-0000-0000-0000-000000000037', 'D', 'Oesophageal squamous cell carcinoma', false, 'Ruled out because this presentation over 2 weeks with associated oral candidal plaques in an immunosuppressed patient is much more consistent with an opportunistic infection than a new malignancy, which would be a less likely explanation at this stage.', 4),
('e7000000-0000-0000-0000-000000000037', 'E', $x$Kaposi's sarcoma of the oesophagus$x$, false, $x$Ruled out because although Kaposi's sarcoma can affect the gastrointestinal tract in advanced HIV, the described oral findings (scrapable white plaques) are classic for candidiasis, making this the more likely diagnosis.$x$, 5),
('e7000000-0000-0000-0000-000000000038', 'A', 'Her partners will automatically be informed of her diagnosis and identity by the clinic without her consent', false, $x$Ruled out because confidentiality is a cornerstone of sexual health services; partners are not informed of the index patient's identity without consent, and full disclosure of her identity would not occur automatically.$x$, 1),
('e7000000-0000-0000-0000-000000000038', 'B', 'Partner notification is not something health services assist with; she must inform all partners herself with no support', false, 'Ruled out because sexual health services routinely provide support (including provider-led options where trained staff contact partners without naming the index patient) for partner notification, rather than leaving patients to manage this entirely alone.', 2),
('e7000000-0000-0000-0000-000000000038', 'C', 'Her employer must be informed of her HIV diagnosis for public health reasons', false, 'Ruled out because there is no requirement or justification for informing an employer of an HIV diagnosis; this would breach patient confidentiality and has no public health basis.', 3),
('e7000000-0000-0000-0000-000000000038', 'D', 'Partner notification is only relevant for bacterial STIs, not for HIV', false, 'Ruled out because partner notification is equally important for HIV, allowing partners to access testing, treatment, and PEP/PrEP discussions as appropriate.', 4),
('e7000000-0000-0000-0000-000000000038', 'E', 'Partner notification is encouraged and can be done confidentially, either by the patient themselves or by trained health advisers who contact partners without revealing the identity of the index patient', true, 'Correct. Partner notification is an important part of managing STIs and HIV to allow contacts to be tested and treated; it can be patient-led (the patient informs partners themselves, often with support) or provider-led (a trained health adviser contacts partners), but in either case confidentiality is maintained and the identity of the index patient is not disclosed to contacts without consent.', 5),
('e7000000-0000-0000-0000-000000000039', 'A', 'A single dose of intramuscular ceftriaxone', false, 'Ruled out because intramuscular ceftriaxone is the treatment for gonorrhoea, not chlamydia; chlamydia is treated with doxycycline or azithromycin, and ceftriaxone alone would not treat this infection.', 1),
('e7000000-0000-0000-0000-000000000039', 'B', 'Doxycycline 100 mg twice daily for 7 days', true, 'Correct. Doxycycline 100 mg twice daily for 7 days is the first-line treatment for uncomplicated genital chlamydia infection; it should be accompanied by advice to abstain from sex until she and her partner(s) have completed treatment, and partner notification/treatment of contacts from the preceding 6 months.', 2),
('e7000000-0000-0000-0000-000000000039', 'C', 'Oral metronidazole 400 mg twice daily for 7 days', false, 'Ruled out because metronidazole is used to treat bacterial vaginosis and trichomoniasis, not chlamydia.', 3),
('e7000000-0000-0000-0000-000000000039', 'D', 'Topical clotrimazole', false, 'Ruled out because this is an antifungal used for candidiasis and has no role in treating a bacterial infection like chlamydia.', 4),
('e7000000-0000-0000-0000-000000000039', 'E', 'No treatment is needed as she is asymptomatic', false, 'Ruled out because asymptomatic chlamydia still requires treatment to prevent complications (such as pelvic inflammatory disease and its sequelae) and onward transmission, regardless of symptom status.', 5),
('e7000000-0000-0000-0000-000000000040', 'A', 'A single intramuscular dose of ceftriaxone 1g', true, 'Correct. Current UK guidance recommends ceftriaxone 1g intramuscularly as a single dose as monotherapy first-line treatment for uncomplicated gonorrhoea, reflecting concerns about rising antimicrobial resistance; a test of cure is recommended given the risk of resistant strains, and partner notification/treatment is essential.', 1),
('e7000000-0000-0000-0000-000000000040', 'B', 'Oral doxycycline 100 mg twice daily for 7 days', false, 'Ruled out because doxycycline is the treatment for chlamydia, not gonorrhoea; gonorrhoea requires ceftriaxone due to widespread resistance to older oral agents such as tetracyclines and quinolones.', 2),
('e7000000-0000-0000-0000-000000000040', 'C', 'Oral azithromycin 1g as a single dose, used alone', false, 'Ruled out because azithromycin monotherapy is no longer recommended for gonorrhoea due to rising resistance; ceftriaxone monotherapy is now the standard first-line treatment.', 3),
('e7000000-0000-0000-0000-000000000040', 'D', 'Oral ciprofloxacin 500 mg as a single dose', false, 'Ruled out because Neisseria gonorrhoeae has high rates of resistance to fluoroquinolones such as ciprofloxacin in the UK, meaning this should not be used empirically without confirmed susceptibility.', 4),
('e7000000-0000-0000-0000-000000000040', 'E', 'No antibiotics are required if symptoms resolve spontaneously within a week', false, 'Ruled out because gonorrhoea requires antibiotic treatment regardless of symptom trajectory to prevent complications (e.g. epididymo-orchitis, PID, disseminated infection) and ongoing transmission.', 5),
('e7000000-0000-0000-0000-000000000041', 'A', 'Genital herpes; confirm with viral PCR swab from the lesion', false, 'Ruled out because herpes typically causes multiple painful vesicles/ulcers rather than a single painless indurated ulcer, making syphilis the more likely diagnosis here.', 1),
('e7000000-0000-0000-0000-000000000041', 'B', 'Chancroid; confirm with Gram stain of ulcer exudate', false, 'Ruled out because chancroid (Haemophilus ducreyi) typically causes painful, ragged ulcers with tender lymphadenopathy, which is a different clinical picture, and is rare in the UK.', 2),
('e7000000-0000-0000-0000-000000000041', 'C', 'Primary syphilis; confirm with treponemal serology and/or dark-field microscopy/PCR of a swab from the ulcer base', true, 'Correct. A single painless indurated genital ulcer (chancre) with non-tender regional lymphadenopathy, occurring roughly 3 weeks after exposure, is classic for primary syphilis caused by Treponema pallidum; diagnosis is confirmed with treponemal serology (which may lag behind the appearance of the chancre, requiring repeat testing if initially negative) and/or direct detection (dark-field microscopy or PCR) from the lesion.', 3),
('e7000000-0000-0000-0000-000000000041', 'D', 'Genital warts; confirm with clinical examination alone, no further testing required', false, 'Ruled out because genital warts present as papular or cauliflower-like growths, not a single painless ulcer, and this presentation does not fit that diagnosis.', 4),
('e7000000-0000-0000-0000-000000000041', 'E', 'Lymphogranuloma venereum; confirm with chlamydia NAAT typing', false, 'Ruled out because LGV typically presents with a transient painless papule/ulcer that often goes unnoticed, followed by prominent unilateral tender inguinal lymphadenopathy (bubo) usually in men who have sex with men, which is a different pattern from the indurated chancre with non-tender nodes described here.', 5),
('e7000000-0000-0000-0000-000000000042', 'A', 'Pityriasis rosea; reassure and manage symptomatically', false, 'Ruled out because although pityriasis rosea causes a widespread rash, it does not typically involve the palms and soles or occur with a preceding genital ulcer, lymphadenopathy, and positive syphilis serology.', 1),
('e7000000-0000-0000-0000-000000000042', 'B', 'Guttate psoriasis; treat with topical corticosteroids', false, 'Ruled out because guttate psoriasis presents with small, drop-like scaly plaques usually following streptococcal infection, not palmar/plantar rash with lymphadenopathy and positive syphilis serology.', 2),
('e7000000-0000-0000-0000-000000000042', 'C', 'Drug eruption; stop any recent new medications', false, 'Ruled out because there is no history of new medication provided, and the combination of prior genital ulcer, rash involving palms and soles, lymphadenopathy, and positive treponemal and non-treponemal serology is diagnostic of secondary syphilis, not a drug reaction.', 3),
('e7000000-0000-0000-0000-000000000042', 'D', 'Secondary syphilis; treat with a single dose of intramuscular benzathine penicillin', true, 'Correct. A widespread, non-itchy maculopapular rash involving the palms and soles, with systemic symptoms and lymphadenopathy occurring weeks after a resolved painless genital ulcer, is classic for secondary syphilis; treatment for early syphilis (primary, secondary, or early latent) is a single dose of intramuscular benzathine penicillin, with the patient warned about possible Jarisch-Herxheimer reaction (fever, myalgia) after treatment due to spirochaete lysis.', 4),
('e7000000-0000-0000-0000-000000000042', 'E', 'Measles; isolate and notify public health', false, 'Ruled out because measles causes a different rash pattern (starting on the face and spreading down, with associated coryza and conjunctivitis) and would not explain positive syphilis serology or the preceding genital ulcer.', 5),
('e7000000-0000-0000-0000-000000000043', 'A', 'Intramuscular benzathine penicillin', false, 'Ruled out because penicillin treats syphilis, a bacterial spirochaete infection, and has no antiviral activity against herpes simplex virus.', 1),
('e7000000-0000-0000-0000-000000000043', 'B', 'Oral aciclovir, alongside saline bathing and topical lidocaine gel for symptomatic relief', true, 'Correct. Multiple painful vesicles/ulcers with dysuria and tender inguinal lymphadenopathy in a first episode is characteristic of primary genital herpes simplex virus infection; oral aciclovir (ideally started within 5 days of symptom onset or while new lesions are forming) reduces symptom duration and severity, and saline bathing plus topical anaesthetic gel help with symptomatic relief, including for dysuria.', 2),
('e7000000-0000-0000-0000-000000000043', 'C', 'Topical podophyllotoxin', false, 'Ruled out because podophyllotoxin is used to treat genital warts (a destructive/antimitotic topical agent), not herpes, and would not address a viral ulcerative infection.', 3),
('e7000000-0000-0000-0000-000000000043', 'D', 'Oral doxycycline for 7 days', false, 'Ruled out because doxycycline is an antibiotic used for chlamydia, not an antiviral, and would have no effect on herpes simplex virus infection.', 4),
('e7000000-0000-0000-0000-000000000043', 'E', 'Reassurance only, as the episode will resolve without any treatment being of benefit', false, 'Ruled out because although primary genital herpes is self-limiting, antiviral treatment with aciclovir significantly reduces the severity and duration of symptoms if started promptly, and should be offered rather than withheld.', 5),
('e7000000-0000-0000-0000-000000000044', 'A', 'Vaginal delivery should proceed as planned as herpes in pregnancy carries no risk to the neonate', false, 'Ruled out because primary genital herpes acquired close to delivery carries a substantial risk of severe neonatal herpes infection (which can be life-threatening), making mode of delivery an important consideration, not something to be disregarded.', 1),
('e7000000-0000-0000-0000-000000000044', 'B', 'Aciclovir is contraindicated in pregnancy and should not be given', false, 'Ruled out because aciclovir is considered safe in pregnancy and is recommended for treatment of primary genital herpes at any gestation, as well as for suppressive therapy from 36 weeks in women with recurrent or late primary infection.', 2),
('e7000000-0000-0000-0000-000000000044', 'C', 'This represents recurrent herpes and carries the same very low neonatal risk as a longstanding history of genital herpes', false, 'Ruled out because this is explicitly described as her first-ever episode (primary infection), which carries a substantially higher risk of neonatal transmission than recurrent herpes, particularly when acquired close to term.', 3),
('e7000000-0000-0000-0000-000000000044', 'D', 'The pregnancy should be immediately terminated because of the herpes diagnosis', false, 'Ruled out because a primary herpes diagnosis in the third trimester does not require termination of pregnancy; risk is managed through antiviral treatment, suppressive therapy, and appropriate mode of delivery planning.', 4),
('e7000000-0000-0000-0000-000000000044', 'E', 'Primary genital herpes acquired in the third trimester (within 6 weeks of expected delivery) carries a high risk of neonatal transmission, so caesarean section is recommended to reduce this risk', true, 'Correct. Primary genital herpes infection acquired late in pregnancy (particularly within 6 weeks of delivery) carries a significant risk of neonatal herpes due to the mother not having developed protective antibodies to pass to the baby before delivery; caesarean section is recommended to reduce the risk of transmission during vaginal delivery, alongside maternal aciclovir treatment and neonatal input.', 5),
('e7000000-0000-0000-0000-000000000045', 'A', 'Trichomonas vaginalis infection; treat with metronidazole, and ensure partner notification and treatment', true, $x$Correct. Frothy, yellow-green, malodorous discharge with vulvovaginal irritation, a 'strawberry cervix' (colpitis macularis) on examination, and motile flagellated organisms on wet mount microscopy are classic for Trichomonas vaginalis infection; treatment is with metronidazole, and as this is a sexually transmitted protozoal infection, partner notification and treatment are essential to prevent reinfection.$x$, 1),
('e7000000-0000-0000-0000-000000000045', 'B', 'Bacterial vaginosis; treat with metronidazole but no partner treatment required', false, 'Ruled out because although metronidazole is also used for bacterial vaginosis, the described strawberry cervix and motile flagellated organisms on microscopy are specific for trichomoniasis, which (unlike bacterial vaginosis) requires partner treatment as it is sexually transmitted.', 2),
('e7000000-0000-0000-0000-000000000045', 'C', 'Vulvovaginal candidiasis; treat with topical clotrimazole', false, 'Ruled out because candidiasis typically presents with thick white discharge and itching without the frothy, malodorous discharge, strawberry cervix, or motile organisms described here.', 3),
('e7000000-0000-0000-0000-000000000045', 'D', 'Chlamydial cervicitis; treat with doxycycline', false, 'Ruled out because chlamydia is diagnosed by NAAT, not by identifying motile flagellated organisms on wet mount microscopy, which is specific to trichomoniasis.', 4),
('e7000000-0000-0000-0000-000000000045', 'E', 'Atrophic vaginitis; treat with topical oestrogen', false, 'Ruled out because atrophic vaginitis occurs in the context of oestrogen deficiency and does not cause frothy malodorous discharge, strawberry cervix, or motile organisms on microscopy.', 5),
('e7000000-0000-0000-0000-000000000046', 'A', 'Await chlamydia and gonorrhoea NAAT results before starting any antibiotics', false, 'Ruled out because delaying treatment while awaiting swab results risks worsening tubal damage and long-term complications; empirical treatment should be started immediately based on clinical suspicion in suspected PID.', 1),
('e7000000-0000-0000-0000-000000000046', 'B', 'Start empirical antibiotic treatment for pelvic inflammatory disease (e.g. intramuscular ceftriaxone plus oral doxycycline and metronidazole) without waiting for swab results', true, 'Correct. This presentation (lower abdominal pain, deep dyspareunia, cervical excitation, low-grade fever, negative pregnancy test) is consistent with pelvic inflammatory disease, most commonly caused by ascending chlamydia or gonorrhoea infection; because delayed treatment increases the risk of long-term complications (infertility, ectopic pregnancy, chronic pelvic pain), empirical antibiotic treatment should be started promptly based on clinical suspicion, without waiting for swab or NAAT results.', 2),
('e7000000-0000-0000-0000-000000000046', 'C', 'Arrange urgent pelvic ultrasound before considering any treatment', false, 'Ruled out because ultrasound is not required before starting empirical treatment for clinically suspected PID; it may be useful if a tubo-ovarian abscess or alternative diagnosis is suspected, but should not delay antibiotic treatment.', 3),
('e7000000-0000-0000-0000-000000000046', 'D', 'Reassure and advise simple analgesia only, as symptoms are likely due to ovulation pain', false, 'Ruled out because the combination of cervical excitation, deep dyspareunia, and fever is not consistent with simple ovulation pain and requires treatment for suspected PID to prevent complications.', 4),
('e7000000-0000-0000-0000-000000000046', 'E', 'Refer for diagnostic laparoscopy before starting any treatment', false, 'Ruled out because laparoscopy is not required as a first step in straightforward suspected PID; clinical diagnosis and prompt empirical treatment are appropriate, with laparoscopy reserved for diagnostic uncertainty or non-response to treatment.', 5),
('e7000000-0000-0000-0000-000000000047', 'A', 'This is unrelated to her previous PID, as PID does not affect future fertility', false, 'Ruled out because PID is a major recognised cause of tubal factor infertility, chronic pelvic pain, and increased ectopic pregnancy risk due to tubal scarring, making a causal link plausible and important to consider.', 1),
('e7000000-0000-0000-0000-000000000047', 'B', 'Endometriosis unrelated to her prior infection is the only possible explanation', false, 'Ruled out because although endometriosis is a differential for chronic pelvic pain and infertility, given her clear history of PID, tubal damage from that infection is the most directly relevant and likely explanation to consider first.', 2),
('e7000000-0000-0000-0000-000000000047', 'C', 'Polycystic ovary syndrome is the most likely cause given her age', false, 'Ruled out because there is no mention of features suggestive of PCOS (such as irregular cycles, hirsutism, or metabolic features), and her known history of PID makes tubal factor infertility a much more directly relevant explanation.', 3),
('e7000000-0000-0000-0000-000000000047', 'D', 'Tubal damage and scarring from her previous pelvic inflammatory disease, causing tubal factor infertility', true, 'Correct. Pelvic inflammatory disease is a well-recognised cause of tubal damage and adhesions, which can lead to tubal factor infertility and chronic pelvic pain; the risk of infertility increases with the number and severity of PID episodes, making this a plausible explanation for her ongoing symptoms and difficulty conceiving after a documented episode.', 4),
('e7000000-0000-0000-0000-000000000047', 'E', 'Her difficulty conceiving is unrelated to her reproductive tract and is likely due to male factor infertility alone', false, 'Ruled out because this assumes a cause without supporting evidence, while she has a clear and directly relevant risk factor (previous PID) for tubal damage that should be actively investigated.', 5),
('e7000000-0000-0000-0000-000000000048', 'A', 'Non-gonococcal urethritis, most commonly due to Chlamydia trachomatis, though other organisms such as Mycoplasma genitalium should also be considered when standard testing is negative', true, 'Correct. Non-gonococcal urethritis (NGU) describes urethral inflammation/discharge in the absence of gonorrhoea; chlamydia is the most common identifiable cause, but when chlamydia and gonorrhoea testing are both negative, other organisms such as Mycoplasma genitalium should be considered and specifically tested for, as this affects antibiotic choice due to differing resistance patterns.', 1),
('e7000000-0000-0000-0000-000000000048', 'B', 'This effectively excludes any infective cause, and no further action is needed', false, 'Ruled out because negative chlamydia and gonorrhoea tests do not exclude other causes of urethritis, such as Mycoplasma genitalium or Trichomonas vaginalis, which should be considered and specifically tested for if symptoms persist.', 2),
('e7000000-0000-0000-0000-000000000048', 'C', 'This is diagnostic of gonorrhoea despite the negative NAAT and microscopy results', false, 'Ruled out because both NAAT and microscopy for gonorrhoea are negative, making gonorrhoea very unlikely; treating for gonorrhoea in this context is not supported by the results.', 3),
('e7000000-0000-0000-0000-000000000048', 'D', 'This is most likely due to a urinary tract infection caused by Escherichia coli and should be treated with trimethoprim', false, 'Ruled out because urethral discharge and mild dysuria without other urinary symptoms in a sexually active young man is more suggestive of a sexually transmitted cause of urethritis than a typical E. coli urinary tract infection.', 4),
('e7000000-0000-0000-0000-000000000048', 'E', 'This represents a normal physiological discharge requiring no further investigation', false, 'Ruled out because urethral discharge with dysuria in a man is not a normal physiological finding and warrants further investigation for a sexually transmitted cause of urethritis.', 5),
('e7000000-0000-0000-0000-000000000049', 'A', 'Standard chlamydial proctitis; treat with the usual 7-day course of doxycycline', false, 'Ruled out because the presence of prominent, fluctuant inguinal lymphadenopathy (bubo formation) alongside proctitis is characteristic of LGV specifically, which requires specific serovar testing and a longer 21-day course of doxycycline rather than the standard 7-day regimen.', 1),
('e7000000-0000-0000-0000-000000000049', 'B', 'Gonococcal proctitis; treat with a single dose of ceftriaxone', false, 'Ruled out because although gonorrhoea can cause proctitis, the described prominent fluctuant inguinal lymphadenopathy (bubo) is a hallmark feature of LGV rather than typical gonococcal proctitis.', 2),
('e7000000-0000-0000-0000-000000000049', 'C', 'Anal fissure secondary to constipation; manage with laxatives and topical treatment', false, 'Ruled out because this presentation (mucopurulent discharge, tenesmus, and fluctuant inguinal lymphadenopathy) is not consistent with a simple anal fissure, which would not explain the discharge or lymph node findings.', 3),
('e7000000-0000-0000-0000-000000000049', 'D', 'Perianal abscess; arrange incision and drainage', false, 'Ruled out because the described findings (rectal discharge, tenesmus, and inguinal rather than perianal swelling) point to LGV proctitis rather than a localised perianal abscess.', 4),
('e7000000-0000-0000-0000-000000000049', 'E', 'Lymphogranuloma venereum (LGV)', true, 'Correct. LGV, caused by specific serovars (L1-L3) of Chlamydia trachomatis, classically presents in men who have sex with men as proctitis (anal pain, discharge, tenesmus) with tender, often fluctuant, inguinal lymphadenopathy (buboes); it requires a longer course of doxycycline (typically 21 days) than standard chlamydia infection.', 5),
('e7000000-0000-0000-0000-000000000050', 'A', 'A urine chlamydia and gonorrhoea test alone is sufficient given he is asymptomatic', false, 'Ruled out because urine testing alone can miss infections at other exposed sites such as the rectum or pharynx; comprehensive screening should sample all relevant exposure sites in men who have sex with men.', 1),
('e7000000-0000-0000-0000-000000000050', 'B', 'HIV testing is not necessary unless he has symptoms of an acute illness', false, 'Ruled out because HIV testing should be offered as part of routine comprehensive sexual health screening regardless of symptoms, particularly given his risk profile.', 2),
('e7000000-0000-0000-0000-000000000050', 'C', 'Test for chlamydia and gonorrhoea at all exposed sites (urethral/urine, rectal, and pharyngeal as relevant), alongside syphilis serology, HIV testing, and hepatitis B and C screening, with hepatitis A/B vaccination offered if not already immune', true, 'Correct. Comprehensive sexual health screening in a man who has sex with men with multiple partners should include chlamydia/gonorrhoea NAAT testing from all sites of sexual contact (not just urine, as urethral testing alone can miss rectal or pharyngeal infection), syphilis serology, HIV testing, and hepatitis B/C screening, with hepatitis A and B vaccination offered if he is not already immune, and discussion of PrEP given his ongoing risk.', 3),
('e7000000-0000-0000-0000-000000000050', 'D', 'Hepatitis A and B vaccination is not relevant to sexual health screening', false, 'Ruled out because hepatitis A and B can be sexually transmitted, particularly in men who have sex with men, and vaccination is an important preventive measure to offer if he is not already immune.', 4),
('e7000000-0000-0000-0000-000000000050', 'E', 'Syphilis testing is only indicated if visible lesions are present', false, 'Ruled out because syphilis is frequently asymptomatic or has subtle findings and is included as part of routine comprehensive STI screening regardless of visible lesions, given the serious complications of untreated infection.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e7000000-0000-0000-0000-000000000001', 'Migraine with aura (at any age) is UKMEC 4 for combined hormonal contraception (pill, patch, ring) due to increased ischaemic stroke risk.', 1),
('e7000000-0000-0000-0000-000000000001', 'Migraine without aura is UKMEC 2 below age 35 but becomes UKMEC 3 at or above age 35.', 2),
('e7000000-0000-0000-0000-000000000001', 'Progestogen-only methods are not restricted by migraine with aura and should be offered as the safe alternative.', 3),
('e7000000-0000-0000-0000-000000000002', 'Age ≥35 plus smoking ≥15 cigarettes/day is UKMEC 4 for combined hormonal contraception; age ≥35 smoking <15/day is UKMEC 3.', 1),
('e7000000-0000-0000-0000-000000000002', 'Smoking is a major independent risk factor for both venous and arterial thrombotic disease with oestrogen-containing contraception.', 2),
('e7000000-0000-0000-0000-000000000002', 'Progestogen-only and non-hormonal methods are not restricted by smoking status and should be offered instead.', 3),
('e7000000-0000-0000-0000-000000000003', 'Desogestrel-only pills (e.g. Cerazette) have a 12-hour missed-pill window, in contrast to the 3-hour window of older progestogen-only pills.', 1),
('e7000000-0000-0000-0000-000000000003', 'Missing this window means ovulation inhibition may be lost, requiring condoms for 48 hours and consideration of emergency contraception if unprotected intercourse has occurred.', 2),
('e7000000-0000-0000-0000-000000000004', 'The copper IUD is the most effective emergency contraceptive (>99%) and can be fitted up to 120 hours after unprotected sex, unaffected by weight or enzyme-inducing drugs.', 1),
('e7000000-0000-0000-0000-000000000004', 'Levonorgestrel is licensed up to 72 hours; ulipristal acetate is licensed up to 120 hours but should not be combined with levonorgestrel or used with progestogens for several days around it.', 2),
('e7000000-0000-0000-0000-000000000004', $x$Efficacy of oral emergency contraception falls with increasing time since intercourse, whereas the copper IUD's efficacy does not.$x$, 3),
('e7000000-0000-0000-0000-000000000005', 'DMPA is associated with a reversible reduction in bone mineral density with prolonged use; risks/benefits should be reviewed at 2 years of use.', 1),
('e7000000-0000-0000-0000-000000000005', 'Return of fertility after stopping DMPA may be delayed for up to 12 months, but this is not the same as permanent infertility.', 2),
('e7000000-0000-0000-0000-000000000005', 'DMPA is UKMEC 2 in adolescents under 18 and women over 45 because of bone health considerations.', 3),
('e7000000-0000-0000-0000-000000000006', 'The etonogestrel implant lasts 3 years and commonly causes irregular bleeding, which is the leading cause of early discontinuation.', 1),
('e7000000-0000-0000-0000-000000000006', 'Insertion is into the inner upper arm; deep or incorrect placement risks injury to nearby nerves and vessels, making correct technique and site marking important.', 2),
('e7000000-0000-0000-0000-000000000006', 'Unlike DMPA, fertility returns quickly after implant removal with no delay in ovulation resumption.', 3),
('e7000000-0000-0000-0000-000000000007', 'The levonorgestrel IUS is recommended first-line for heavy menstrual bleeding management alongside contraception, often producing significant reduction in blood loss or amenorrhoea.', 1),
('e7000000-0000-0000-0000-000000000007', 'The copper IUD, in contrast, commonly increases menstrual bleeding and is not used to treat menorrhagia.', 2),
('e7000000-0000-0000-0000-000000000008', 'Combined hormonal contraception is UKMEC 4 in breastfeeding women under 6 weeks postpartum, improving to UKMEC 2 from 6 weeks to 6 months while breastfeeding.', 1),
('e7000000-0000-0000-0000-000000000008', 'Progestogen-only methods (pill, implant) are UKMEC 1 and can be started immediately after delivery regardless of breastfeeding.', 2),
('e7000000-0000-0000-0000-000000000008', 'Lactational amenorrhoea alone is only a reliable contraceptive method under strict criteria and should not be relied upon as sole contraception long-term.', 3),
('e7000000-0000-0000-0000-000000000009', 'Enzyme-inducing drugs (carbamazepine, phenytoin, rifampicin, some antiretrovirals) reduce efficacy of the COCP, POP, implant, and vaginal ring/patch.', 1),
('e7000000-0000-0000-0000-000000000009', 'The copper IUD, levonorgestrel IUS, and DMPA injection are not significantly affected by enzyme induction and are preferred choices in these patients.', 2),
('e7000000-0000-0000-0000-000000000010', 'Positive antiphospholipid antibodies (with or without lupus) are UKMEC 4 for all combined hormonal contraceptive methods due to thrombosis risk.', 1),
('e7000000-0000-0000-0000-000000000010', 'SLE itself may range from UKMEC 2 to UKMEC 4 depending on the presence of antiphospholipid antibodies, severe disease, or immunosuppression.', 2),
('e7000000-0000-0000-0000-000000000010', 'Progestogen-only and non-hormonal methods remain appropriate options in this group.', 3),
('e7000000-0000-0000-0000-000000000011', 'Vasectomy is not immediately effective; contraception must continue until azoospermia is confirmed on post-procedure semen analysis, typically around 12 weeks later.', 1),
('e7000000-0000-0000-0000-000000000011', 'Vasectomy has a small long-term failure rate due to recanalisation (~1 in 2000), which should be part of informed consent.', 2),
('e7000000-0000-0000-0000-000000000011', 'Vasectomy does not protect against sexually transmitted infections.', 3),
('e7000000-0000-0000-0000-000000000012', 'BMI 30-34 is UKMEC 2 and BMI ≥35 is UKMEC 3 for combined hormonal contraception due to increased VTE risk.', 1),
('e7000000-0000-0000-0000-000000000012', 'Non-oestrogen-containing methods (IUS, implant, DMPA, copper IUD) are not restricted by BMI and are preferable options in significant obesity.', 2),
('e7000000-0000-0000-0000-000000000013', 'The copper IUD commonly causes heavier and more painful periods, in contrast to the levonorgestrel IUS which typically reduces menstrual bleeding.', 1),
('e7000000-0000-0000-0000-000000000013', 'Symptomatic management with tranexamic acid and/or NSAIDs is appropriate first-line if the patient wishes to continue with the copper IUD.', 2),
('e7000000-0000-0000-0000-000000000014', $x$Lichen sclerosus classically causes vulval/perianal itching with white atrophic 'figure-of-eight' plaques and skin fragility; first-line treatment is potent topical corticosteroid.$x$, 1),
('e7000000-0000-0000-0000-000000000014', 'There is a small but important lifetime risk (~5%) of vulval squamous cell carcinoma, so long-term follow-up and biopsy of any non-healing or atypical area is important.', 2),
('e7000000-0000-0000-0000-000000000015', 'Balanitis xerotica obliterans is lichen sclerosus affecting the male genitalia, causing progressive whitish scarring of the glans/prepuce and phimosis.', 1),
('e7000000-0000-0000-0000-000000000015', 'First-line treatment is potent topical corticosteroid; circumcision may be required for persistent or severe phimosis, and biopsy is warranted if atypical/non-healing areas develop given a small malignancy risk.', 2),
('e7000000-0000-0000-0000-000000000016', $x$Bartholin's abscess presents as a tender, fluctuant swelling at the posterior introitus; treatment is incision and drainage (word catheter or marsupialisation), not antibiotics alone.$x$, 1),
('e7000000-0000-0000-0000-000000000016', $x$In women over 40, a Bartholin's gland swelling should raise consideration of Bartholin's gland carcinoma, and biopsy of the gland wall should be considered.$x$, 2),
('e7000000-0000-0000-0000-000000000017', 'Podophyllotoxin and podophyllin are contraindicated in pregnancy due to teratogenicity and cytotoxicity; cryotherapy is generally preferred.', 1),
('e7000000-0000-0000-0000-000000000017', 'Genital warts caused by HPV types 6 and 11 often grow larger and more numerous during pregnancy due to relative immunosuppression and increased vascularity, but typically do not require delivery by caesarean unless they obstruct the birth canal.', 2),
('e7000000-0000-0000-0000-000000000018', 'Candidal balanitis presents with erythema and satellite pustules/papules on the glans and is strongly associated with poorly controlled diabetes; check blood glucose in new or recurrent cases.', 1),
('e7000000-0000-0000-0000-000000000018', 'First-line treatment is a topical imidazole antifungal; recurrent cases should prompt screening for undiagnosed diabetes.', 2),
('e7000000-0000-0000-0000-000000000019', $x$Epididymo-orchitis causes gradual-onset unilateral scrotal pain/swelling with a positive Prehn's sign and preserved cremasteric reflex, unlike torsion.$x$, 1),
('e7000000-0000-0000-0000-000000000019', 'In sexually active men under 35, chlamydia and gonorrhoea are the most likely causes; in older men or those with lower urinary tract symptoms, coliforms (e.g. E. coli) are more likely, guiding antibiotic choice.', 2),
('e7000000-0000-0000-0000-000000000019', 'Testicular torsion must always be actively excluded first in acute scrotal pain, as it is a time-critical surgical emergency.', 3),
('e7000000-0000-0000-0000-000000000020', $x$Testicular torsion presents with sudden severe pain, a high-riding horizontal testis, absent cremasteric reflex, and no relief with elevation (negative Prehn's sign) — features that distinguish it from epididymo-orchitis.$x$, 1),
('e7000000-0000-0000-0000-000000000020', 'Torsion is a time-critical surgical emergency; testicular salvage rates fall sharply after 6 hours, so clinical suspicion should prompt immediate surgical exploration rather than delay for imaging.', 2),
('e7000000-0000-0000-0000-000000000021', 'A hydrocele is a painless, soft, transilluminating scrotal swelling due to fluid collection around the testis, which itself feels normal (though may be difficult to palpate).', 1),
('e7000000-0000-0000-0000-000000000021', $x$In contrast, a varicocele feels like a 'bag of worms', is not transilluminable, and an epididymal cyst is a discrete cystic swelling separate from the testis.$x$, 2),
('e7000000-0000-0000-0000-000000000021', 'Any new scrotal swelling in a young man should prompt examination to exclude a testicular mass, and ultrasound is used where the testis cannot be adequately assessed clinically.', 3),
('e7000000-0000-0000-0000-000000000022', 'Molluscum contagiosum causes firm, umbilicated, pearly papules; in adults with genital lesions, sexual transmission should prompt a full STI screen.', 1),
('e7000000-0000-0000-0000-000000000022', 'Distinguish from pearly penile papules (uniform rows around the corona, no umbilication, a normal variant) and genital warts (irregular, cauliflower-like surface).', 2),
('e7000000-0000-0000-0000-000000000023', 'Lichen sclerosus carries a lifetime risk of vulval squamous cell carcinoma of approximately 5%; any new ulceration, induration, or lesion resistant to treatment warrants urgent biopsy.', 1),
('e7000000-0000-0000-0000-000000000023', 'Persistent bleeding, non-healing ulceration, or a new lump in a patient with known lichen sclerosus should never be attributed to the underlying condition without excluding malignancy first.', 2),
('e7000000-0000-0000-0000-000000000024', 'Pearly penile papules are a benign, common anatomical variant appearing as uniform rows of small papules around the corona of the glans, requiring only reassurance.', 1),
('e7000000-0000-0000-0000-000000000024', 'They are distinguished from genital warts by their symmetrical, uniform appearance and lack of change over time, and are not sexually transmitted.', 2),
('e7000000-0000-0000-0000-000000000025', $x$Fournier's gangrene is a rapidly progressive necrotising fasciitis of the perineum/scrotum, more common in diabetic or immunocompromised patients, and is a surgical emergency.$x$, 1),
('e7000000-0000-0000-0000-000000000025', 'Pain disproportionate to visible skin findings, crepitus, and systemic sepsis are red flags for necrotising fasciitis; management is immediate IV antibiotics, resuscitation, and emergency debridement without delay for imaging.', 2),
('e7000000-0000-0000-0000-000000000026', $x$Bacterial vaginosis is diagnosed using the Amsel criteria: thin homogenous discharge, vaginal pH >4.5, positive amine ('whiff') test, and clue cells on microscopy (at least 3 of 4).$x$, 1),
('e7000000-0000-0000-0000-000000000026', 'It results from loss of normal vaginal lactobacilli and overgrowth of anaerobes (e.g. Gardnerella vaginalis); first-line treatment is metronidazole, and recurrence is common.', 2),
('e7000000-0000-0000-0000-000000000026', 'Unlike most STIs, bacterial vaginosis is not classically considered sexually transmitted, though it is associated with sexual activity and can recur with new partners.', 3),
('e7000000-0000-0000-0000-000000000027', 'PEP for sexual exposure should ideally start within 24 hours and is generally not offered beyond 72 hours after the exposure, as efficacy diminishes rapidly with time.', 1),
('e7000000-0000-0000-0000-000000000027', 'A standard PEP regimen involves combination antiretroviral therapy for 28 days followed by HIV testing at the end of the window period.', 2),
('e7000000-0000-0000-0000-000000000027', 'PEP is distinct from PrEP, which is taken before or around anticipated future exposures rather than after a single event that has already occurred.', 3),
('e7000000-0000-0000-0000-000000000028', 'PrEP (tenofovir/emtricitabine) is highly effective for HIV prevention in individuals at ongoing substantial risk and can be taken daily or via an event-based regimen for planned exposures.', 1),
('e7000000-0000-0000-0000-000000000028', 'Before starting and during PrEP use, regular HIV testing is essential to avoid inadvertently treating undiagnosed HIV infection with an incomplete regimen, which risks drug resistance.', 2),
('e7000000-0000-0000-0000-000000000028', $x$Renal function should be monitored periodically because of tenofovir's nephrotoxic potential.$x$, 3),
('e7000000-0000-0000-0000-000000000029', '4th generation HIV antigen/antibody tests can detect most infections from about 4 weeks after exposure, but a confirmatory negative test at 8-12 weeks is needed to definitively exclude infection from a specific exposure.', 1),
('e7000000-0000-0000-0000-000000000029', 'Point-of-care antibody-only tests generally have a longer window period than laboratory 4th generation tests and are less reliable in early infection.', 2),
('e7000000-0000-0000-0000-000000000030', 'HIV seroconversion illness typically occurs 2-4 weeks after exposure with fever, pharyngitis, lymphadenopathy, and a maculopapular rash, closely mimicking glandular fever.', 1),
('e7000000-0000-0000-0000-000000000030', 'It is frequently missed because the presentation is non-specific; a history of recent sexual risk exposure should prompt HIV testing even when other diagnoses seem plausible.', 2),
('e7000000-0000-0000-0000-000000000031', 'Pneumocystis jirovecii pneumonia is an AIDS-defining illness typically occurring at CD4 <200, presenting with subacute dyspnoea, dry cough, and exertional oxygen desaturation, often with a relatively unremarkable chest examination.', 1),
('e7000000-0000-0000-0000-000000000031', 'First-line treatment is high-dose co-trimoxazole; adjunctive corticosteroids are used in significant hypoxaemia.', 2),
('e7000000-0000-0000-0000-000000000031', 'A new HIV diagnosis presenting with an opportunistic infection like PCP indicates advanced immunosuppression and should prompt urgent initiation of antiretroviral therapy and opportunistic infection prophylaxis planning.', 3),
('e7000000-0000-0000-0000-000000000032', 'Vaginal delivery is recommended when maternal HIV viral load is undetectable (<50 copies/mL) near delivery; caesarean section is advised for higher viral loads (generally >400 copies/mL).', 1),
('e7000000-0000-0000-0000-000000000032', 'Antiretroviral therapy is continued throughout pregnancy to maintain viral suppression, and the neonate receives post-exposure antiretroviral prophylaxis regardless of maternal viral load.', 2),
('e7000000-0000-0000-0000-000000000032', 'UK guidance generally recommends formula feeding to minimise residual transmission risk, although this is increasingly individualised with specialist support for well-suppressed mothers who wish to breastfeed.', 3),
('e7000000-0000-0000-0000-000000000033', 'First aid for needlestick injury: wash with soap and water, encourage gentle bleeding, do not suck the wound; report immediately to occupational health.', 1),
('e7000000-0000-0000-0000-000000000033', $x$Risk assessment considers the injury type (hollow-bore, visible blood, depth), source patient's risk factors and testing (with consent), and determines whether PEP is indicated.$x$, 2),
('e7000000-0000-0000-0000-000000000033', 'PEP is most effective when started as soon as possible after exposure, so delay in reporting reduces its effectiveness.', 3),
('e7000000-0000-0000-0000-000000000034', 'HBsAg positive for over 6 months defines chronic hepatitis B infection; anti-HBc IgG indicates past or current infection, while isolated anti-HBs indicates vaccine-induced immunity.', 1),
('e7000000-0000-0000-0000-000000000034', 'HBeAg positivity generally reflects high viral replication/infectivity, while HBeAg-negative/anti-HBe-positive status often reflects lower replication, though viral load (HBV DNA) should still be checked as some patients have precore mutant virus with ongoing high replication despite HBeAg negativity.', 2),
('e7000000-0000-0000-0000-000000000035', 'Hepatitis C antibody positivity indicates past exposure only; HCV RNA (PCR) testing is required to confirm active/chronic infection requiring treatment.', 1),
('e7000000-0000-0000-0000-000000000035', 'Unlike hepatitis A and B, there is no vaccine against hepatitis C; management of confirmed active infection is with direct-acting antiviral therapy, which achieves high cure rates.', 2),
('e7000000-0000-0000-0000-000000000036', $x$Sustained undetectable viral load on effective antiretroviral therapy means a person with HIV cannot sexually transmit the virus to partners ('U=U').$x$, 1),
('e7000000-0000-0000-0000-000000000036', 'This message is central to reducing HIV-related stigma, though barrier methods remain relevant for prevention of other STIs and unplanned pregnancy.', 2),
('e7000000-0000-0000-0000-000000000037', 'Oesophageal candidiasis is an AIDS-defining illness, typically occurring at CD4 <200, presenting with odynophagia/dysphagia often alongside visible oral candidiasis.', 1),
('e7000000-0000-0000-0000-000000000037', 'Treatment is with systemic antifungal therapy (e.g. fluconazole); its occurrence should prompt urgent HIV treatment optimisation and opportunistic infection screening.', 2),
('e7000000-0000-0000-0000-000000000038', $x$Partner notification for STIs/HIV can be patient-led or provider-led, and maintains confidentiality of the index patient's identity when contacting partners.$x$, 1),
('e7000000-0000-0000-0000-000000000038', 'Sexual health services actively support partner notification because timely partner testing and treatment reduces onward transmission and allows partners appropriate care.', 2),
('e7000000-0000-0000-0000-000000000039', 'Doxycycline 100 mg twice daily for 7 days is first-line for uncomplicated chlamydia; azithromycin 1g single dose is an alternative, particularly in pregnancy where doxycycline is avoided.', 1),
('e7000000-0000-0000-0000-000000000039', 'Most chlamydia infections are asymptomatic, but treatment is still required to prevent complications like PID and further transmission; partner notification covers contacts from the preceding 6 months.', 2),
('e7000000-0000-0000-0000-000000000040', 'Ceftriaxone 1g IM as a single dose is current first-line monotherapy for gonorrhoea in the UK, reflecting concerns about resistance to other antibiotic classes.', 1),
('e7000000-0000-0000-0000-000000000040', 'Test of cure is recommended after treatment for gonorrhoea due to the risk of resistant organisms, unlike routine chlamydia treatment.', 2),
('e7000000-0000-0000-0000-000000000040', 'Fluoroquinolone and macrolide resistance in N. gonorrhoeae mean these should not be used as empirical monotherapy.', 3),
('e7000000-0000-0000-0000-000000000041', 'Primary syphilis presents as a single, painless, indurated genital ulcer (chancre) with non-tender regional lymphadenopathy, typically 2-4 weeks after exposure.', 1),
('e7000000-0000-0000-0000-000000000041', 'Diagnosis uses treponemal serology (EIA/TPPA) and non-treponemal tests (RPR/VDRL for monitoring), plus direct detection (dark-field microscopy or PCR) from the ulcer if available; serology may be falsely negative very early in primary syphilis.', 2),
('e7000000-0000-0000-0000-000000000041', 'First-line treatment for early syphilis is a single dose of intramuscular benzathine penicillin.', 3),
('e7000000-0000-0000-0000-000000000042', 'Secondary syphilis classically causes a widespread maculopapular rash involving the palms and soles, with systemic symptoms and generalised lymphadenopathy, occurring weeks after the primary chancre resolves.', 1),
('e7000000-0000-0000-0000-000000000042', 'Treatment for early syphilis (primary/secondary/early latent) is a single dose of IM benzathine penicillin; late latent syphilis requires a longer course.', 2),
('e7000000-0000-0000-0000-000000000042', 'The Jarisch-Herxheimer reaction (fever, myalgia, worsening rash) can occur within hours of treatment due to rapid spirochaete killing and should be anticipated and explained to the patient.', 3),
('e7000000-0000-0000-0000-000000000043', 'Primary genital herpes presents with multiple painful vesicles/ulcers, dysuria, and tender inguinal lymphadenopathy; oral aciclovir started early reduces symptom severity and duration.', 1),
('e7000000-0000-0000-0000-000000000043', 'Urinary retention can occur due to pain and local swelling; catheterisation may rarely be required, and simple measures like bathing in a warm bath while voiding can help.', 2),
('e7000000-0000-0000-0000-000000000043', 'Recurrent episodes are usually milder and shorter; frequent recurrences may be managed with episodic or suppressive aciclovir therapy.', 3),
('e7000000-0000-0000-0000-000000000044', 'Primary genital herpes acquired within 6 weeks of delivery carries a high risk of neonatal transmission due to lack of maternal antibody transfer; caesarean section is recommended in this scenario.', 1),
('e7000000-0000-0000-0000-000000000044', 'Recurrent herpes or primary infection acquired earlier in pregnancy (with time for antibody development and suppressive therapy from 36 weeks) carries a much lower risk, and vaginal delivery is often still appropriate.', 2),
('e7000000-0000-0000-0000-000000000044', 'Aciclovir is safe throughout pregnancy and is used both to treat the acute episode and as suppressive therapy from 36 weeks to reduce recurrence risk at delivery.', 3),
('e7000000-0000-0000-0000-000000000045', $x$Trichomonas vaginalis causes frothy, yellow-green, malodorous discharge, vulvovaginal irritation, and a 'strawberry cervix'; diagnosis is confirmed by seeing motile flagellated protozoa on wet mount or via NAAT.$x$, 1),
('e7000000-0000-0000-0000-000000000045', 'Unlike bacterial vaginosis, trichomoniasis is a sexually transmitted infection requiring partner notification and treatment, and both are treated with metronidazole.', 2),
('e7000000-0000-0000-0000-000000000046', 'Pelvic inflammatory disease should be treated empirically based on clinical suspicion (lower abdominal pain, cervical excitation, adnexal tenderness) without waiting for swab confirmation, as delay increases risk of long-term complications.', 1),
('e7000000-0000-0000-0000-000000000046', 'The most common causative organisms are Chlamydia trachomatis and Neisseria gonorrhoeae, so empirical treatment covers both alongside anaerobic cover (e.g. ceftriaxone, doxycycline, and metronidazole).', 2),
('e7000000-0000-0000-0000-000000000047', 'PID is an important cause of tubal factor infertility, chronic pelvic pain, and increased risk of ectopic pregnancy due to tubal scarring and adhesions.', 1),
('e7000000-0000-0000-0000-000000000047', 'The risk of these complications increases with repeated or delayed-treated episodes of PID, reinforcing the importance of prompt empirical treatment when PID is suspected.', 2),
('e7000000-0000-0000-0000-000000000047', 'Fitz-Hugh-Curtis syndrome (perihepatitis causing right upper quadrant pain) is another recognised complication of PID resulting from spread of infection.', 3),
('e7000000-0000-0000-0000-000000000048', 'Non-gonococcal urethritis is most commonly caused by Chlamydia trachomatis; when standard chlamydia/gonorrhoea testing is negative, Mycoplasma genitalium should be considered as an important alternative cause.', 1),
('e7000000-0000-0000-0000-000000000048', 'Mycoplasma genitalium has high rates of macrolide resistance, so specific testing (including resistance testing where available) guides antibiotic choice, differing from standard chlamydia treatment.', 2),
('e7000000-0000-0000-0000-000000000049', 'LGV, caused by L1-L3 serovars of Chlamydia trachomatis, presents with proctitis and/or tender, sometimes fluctuant, inguinal lymphadenopathy (buboes), particularly in men who have sex with men.', 1),
('e7000000-0000-0000-0000-000000000049', 'Treatment requires a longer course of doxycycline (typically 21 days) compared to standard chlamydia infection (7 days), reflecting the more invasive nature of LGV serovars.', 2),
('e7000000-0000-0000-0000-000000000050', 'Comprehensive STI screening in MSM should sample all exposed sites (urine/urethral, rectal, pharyngeal) for chlamydia/gonorrhoea, as infection at non-genital sites is commonly missed by urine testing alone.', 1),
('e7000000-0000-0000-0000-000000000050', 'Routine screening should also include syphilis serology, HIV testing, and hepatitis B/C screening, with hepatitis A/B vaccination and PrEP discussion offered where appropriate given ongoing risk.', 2);
